		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local s = data.topLooper\nlocal cfg = data.topLooperSettings\nif s == nil or cfg == nil or s.drawMine == nil then\n    self.used = true\n    return\nend\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil or me.hp.current <= 0 then\n    self.used = true\n    return\nend\nlocal values = cfg.values\nlocal y = me.pos.y\n\n-- Red: where I go next.\nlocal nextSpot = s.nextSpot\nif nextSpot and values.nextRing then\n    s.drawNext:addCircle(nextSpot.x, y, nextSpot.z, 0.8)\n    if nextSpot.tower then\n        s.drawNext:addDonut(nextSpot.tower.x, y, nextSpot.tower.z, 2.6, 3.2)\n    end\nend\n\n-- Where I go now: a red circle on the spot, the tower ring in green, and an arrow sized and drawn like [Lj Draw] Arrow to Black Hole.\nlocal spot = s.spot\nif spot then\n    (s.drawSpot or s.drawMine):addCircle(spot.x, y, spot.z, 0.8)\n    if spot.tower then\n        s.drawMine:addDonut(spot.tower.x, y, spot.tower.z, 2.6, 3.2)\n    end\n    if values.arrow then\n        local dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\n        local dist = math.sqrt(dx * dx + dz * dz)\n        local scale = math.min(1, dist / 15)\n        local tipLength = math.max(2, 3 * scale)\n        local baseLength = dist - tipLength\n        if baseLength > 1 then\n            s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n                baseLength, math.max(0.5, scale), tipLength, math.max(1.5, 3 * scale),\n                false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n        end\n    end\nend\nself.used = true\n",
							name = "Draw Guidance",
							uuid = "d5a315ab-42c6-c473-80ea-8f625a15f2be",
							version = 2.1,
						},
					},
				},
				conditions = 
				{
				},
				eventType = 12,
				loop = true,
				mechanicTime = 15,
				name = "[Looper] Guidance",
				timeRange = true,
				timelineIndex = 3,
				timerEndOffset = 45,
				timerStartOffset = -5,
				uuid = "4c5c371d-5ea2-47c3-842c-22c6a5e6886c",
				version = 2,
			},
		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "local s = data.topLooper\nlocal cfg = data.topLooperSettings\nif s == nil or cfg == nil or s.queue == nil then\n    self.used = true\n    return\nend\nlocal queue = s.queue\nlocal count = #queue\nfor i = 1, count do\n    local call = queue[i]\n    if cfg.values.callouts then\n        TensorCore.addAlertText(2500, call.text, 1.5, call.prio, call.tts and cfg.values.tts)\n    end\n    queue[i] = nil\nend\nself.used = true\n",
							name = "Announce Callouts",
							uuid = "ca48d296-48ac-65f6-ba69-e9eaf401f42a",
							version = 2.1,
						},
					},
				},
				conditions = 
				{
				},
				loop = true,
				mechanicTime = 15,
				name = "[Looper] Callouts",
				timeRange = true,
				timelineIndex = 3,
				timerEndOffset = 45,
				timerStartOffset = -5,
				uuid = "f301ef5c-5e4d-5a60-af5b-30dbe1fd7134",
				version = 2,
			},
		},
		
		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\nif data.topLooperOptionsClosed then\n    self.used = true\n    return\nend\nif cfg.sections == nil then\n    -- A row with a range is a slider; without one it is a checkbox; \"style\" makes an Arrow/Tether choice; \"choice\" picks from\n    -- the list in the row's 4th field. A new setting only\n    -- needs a row and a default.\n    -- In fight order. Each section runs arrow, spots, labels, then warnings and extras; draws that overlap something else are off by default.\n    cfg.sections = {\n        { \"All mechanics\", {\n            { \"rosterOpen\", \"Open Party Roster at the start\" },\n            { \"labelSize\", \"Spot label size\", 1, 3, \"%.1f\" },\n            { \"tts\", \"Callout text-to-speech\" },\n            { \"mitOn\", \"Mitigation (from the mit sheet)\" },\n        } },\n        { \"P1  Program Loop\", {\n            { \"arrow\", \"Arrow##loop\" },\n            { \"stLoop\", \"Arrow or tether##loop\", \"style\" },\n            { \"nextRing\", \"Next-spot ring\" },\n            { \"callouts\", \"Callouts\" },\n            { \"topUp\", \"Tank/healer top-up reminder\" },\n            { \"tetherRadius\", \"Tether spot distance (y)\", 12, 19, \"%.1f\" },\n            { \"tetherAngle\", \"Tether cheat angle (deg)\", 0, 14, \"%.0f\" },\n            { \"grabDistance\", \"Tether grab distance from boss (y)\", 2, 9, \"%.1f\" },\n            { \"towerOffset\", \"Tower off-centre (y)\", 0, 2.5, \"%.1f\" },\n        } },\n        { \"P1  Pantokrator\", {\n            { \"panCallouts\", \"Flex and bait callouts\" },\n        } },\n        { \"P2  Party Synergy\", {\n            { \"synArrow\", \"Arrow##syn\" },\n            { \"stSyn\", \"Arrow or tether##syn\", \"style\" },\n            { \"synSpots\", \"Spots##syn\" },\n            { \"synLabels\", \"My label##syn\" },\n            { \"synOthers\", \"Other roles' labels##syn\" },\n            { \"synFlex\", \"Flex reminder\" },\n            { \"synFlexRule\", \"Which stack flexes\", \"choice\", { \"Strat default\", \"Closest to eye\", \"Furthest from eye\" } },\n            { \"synKnock\", \"Knockback spots\" },\n            { \"synAoe\", \"Optical Laser draw (boss attack)\" },\n        } },\n        { \"P2  Limitless Synergy\", {\n            { \"limTank\", \"Tank tether arrow\" },\n            { \"limAoe\", \"Sagittarius Arrow draw (boss attack)\" },\n            { \"stLim\", \"Arrow or tether##lim\", \"style\" },\n        } },\n        { \"P3  Intermission\", {\n            { \"intArrow\", \"Arrow##int\" },\n            { \"stInt\", \"Arrow or tether##int\", \"style\" },\n            { \"intSpots\", \"Spots##int\" },\n            { \"intLabels\", \"Labels##int\" },\n        } },\n        { \"P3  Hello World\", {\n            { \"helArrow\", \"Arrow##hel\" },\n            { \"stHel\", \"Arrow or tether##hel\", \"style\" },\n            { \"helSpots\", \"Spots##hel\" },\n            { \"helLabels\", \"Labels##hel\" },\n            { \"helConga\", \"Conga spots after Critical Error\" },\n        } },\n        { \"P3  Monitors\", {\n            { \"monArrow\", \"Arrow##mon\" },\n            { \"stMon\", \"Arrow or tether##mon\", \"style\" },\n            { \"monRing\", \"Ring##mon\" },\n            { \"monFace\", \"Face lock##mon\" },\n            { \"monFacing\", \"Facing line (if not face locking)\" },\n            { \"monSouth\", \"Monitor 3 extra south (y)\", 0, 5, \"%.1f\" },\n        } },\n        { \"P4  Wave Cannons\", {\n            { \"wcAoe\", \"Wave Cannon line draws (boss attack)\" },\n        } },\n        { \"P5  Delta\", {\n            { \"delArrow\", \"Arrow##del\" },\n            { \"stDel\", \"Arrow or tether##del\", \"style\" },\n            { \"delSpots\", \"Spots##del\" },\n            { \"delLabels\", \"My label##del\" },\n            { \"delOthers\", \"Other roles' labels##del\" },\n            { \"delBreak\", \"Tether break warning\" },\n            { \"delSwap\", \"Fist swap reminder\" },\n            { \"delMonitor\", \"Monitor guidance\" },\n            { \"delFace\", \"Face lock##del\" },\n            { \"delOtherBeams\", \"Other players' monitor beams\" },\n            { \"delBossHalf\", \"Final Omega's monitor half\" },\n            { \"delAoe\", \"Optical Laser and fist puddle draws (boss attacks)\" },\n        } },\n        { \"P5  Sigma\", {\n            { \"sigArrow\", \"Arrow##sig\" },\n            { \"stSig\", \"Arrow or tether##sig\", \"style\" },\n            { \"sigSpots\", \"Spots##sig\" },\n            { \"sigLabels\", \"My label##sig\" },\n            { \"sigOthers\", \"Other roles' labels##sig\" },\n            { \"sigAoe\", \"Rear Lasers draw (boss attack)\" },\n        } },\n        { \"P5  Omega\", {\n            { \"omeArrow\", \"Arrow##ome\" },\n            { \"stOme\", \"Arrow or tether##ome\", \"style\" },\n            { \"omeSpots\", \"Spots##ome\" },\n            { \"omeLabels\", \"Labels##ome\" },\n            { \"omeClones\", \"Clone attack predraws (your MuAi cones cover it)\" },\n            { \"omeSafe\", \"  Clone predraws as safe area (off: red attacks)\" },\n            { \"omePreview\", \"  Preview the next pair (red attacks)\" },\n        } },\n        { \"P5  World bounces\", {\n            { \"worldDraw\", \"Near/Far bounce prediction\" },\n        } },\n        { \"P6  Exasquares\", {\n            { \"exaArrow\", \"Dodge arrow##exa\" },\n            { \"stExa\", \"Arrow or tether##exa\", \"style\" },\n            { \"exaDpsSupport\", \"  Side dodges##exa\" },\n            { \"exaZone\", \"Line draws##exa\" },\n            { \"exaSafe\", \"  Line draws as safe area (off: red lines)##exa\" },\n        } },\n        { \"P6  Unlimited Wave Cannon\", {\n            { \"uwcArrow\", \"Exaflare puddle arrow (both)\" },\n            { \"stUwc\", \"Arrow or tether##uwc\", \"style\" },\n        } },\n        { \"P6  Clock spots\", {\n            { \"clkWave\", \"Wave Cannon 1 clock spot arrow\" },\n            { \"clkMeteor\", \"Cosmo Meteor arrow\" },\n            { \"clkFlare\", \"Flare marker arrow\" },\n            { \"stClk\", \"Arrow or tether##clk\", \"style\" },\n        } },\n    }\n    -- The user's settings on 2026-11-08, saved as the NA preset. Every row has a value here.\n    cfg.presets = {\n        NA = {\n            rosterOpen = false, labelSize = 1.5, tts = false, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            arrow = true, nextRing = true, callouts = false, topUp = false,\n            tetherRadius = 16, tetherAngle = 0, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            synFlexRule = \"Strat default\",\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = false, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n    }\nend\nlocal values = cfg.values\nlocal visible, open = GUI:Begin(\"Masado's draws###TopLooperOptions\", true, GUI.WindowFlags_AlwaysAutoResize)\nif visible then\n    local Roster = AnyoneCore and AnyoneCore.Roster\n    if Roster ~= nil and Roster.current() ~= nil then\n        local slot = Roster.mySlot()\n        local base = (slot == \"H1\" or slot == \"R1\" or slot == \"M1\" or slot == \"T1\") and \"G1\" or \"G2\"\n        GUI:TextColored(0.4, 1, 0.4, 1, \"Party Roster: \" .. tostring(slot) .. \", base group \" .. base)\n    else\n        GUI:TextColored(1, 0.4, 0.4, 1, \"Party Roster not set: flex and role spots won't work\")\n    end\n    local popup = AnyoneCore and AnyoneCore.RosterPopup\n    if popup and popup.openManual and GUI:Button(\"Edit Party Roster\") then\n        popup.openManual()\n    end\n    GUI:Spacing()\n    -- Strat presets, laid out like Frog Draws on DSR: plain name buttons, the strat in use drawn green. NA applies the user's\n    -- saved settings (NA guides); Elemental (ffxiv.tuufless.com/elemental/top) and OCE (materiaraiding.com/ultimate/top)\n    -- only switch the strat, for the solvers that have it. LDPU is the user's name for the raidplan/toolbox guides (2026-11-08).\n    GUI:Text(\"Preset\")\n    -- Mana: the JP Mana guide (lodestone blog 5536808).\n    local current = values.mana and \"Mana\" or values.ldpu and \"LDPU\" or values.oce and \"OCE\" or values.elemental and \"Elemental\" or \"NA\"\n    for i, strat in ipairs({ \"NA\", \"Elemental\", \"OCE\", \"LDPU\", \"Mana\" }) do\n        if i > 1 then GUI:SameLine() end\n        local lit = strat == current\n        if lit then\n            GUI:PushStyleColor(GUI.Col_Button, 0.15, 0.55, 0.2, 1)\n            GUI:PushStyleColor(GUI.Col_ButtonHovered, 0.2, 0.65, 0.25, 1)\n        end\n        if GUI:Button(strat .. \"##TopStrat\") then\n            if strat == \"NA\" then\n                for key, value in pairs(cfg.presets.NA) do\n                    if cfg.defaults[key] ~= nil then values[key] = value end\n                end\n            end\n            values.elemental = strat == \"Elemental\"\n            values.oce = strat == \"OCE\"\n            values.ldpu = strat == \"LDPU\"\n            values.mana = strat == \"Mana\"\n            cfg.dirty = true\n        end\n        if lit then GUI:PopStyleColor(2) end\n    end\n    -- LDPU's second Exasquare already uses the \"Side dodges\" layout, so the box shows ticked while LDPU is the preset (the user,\n    -- 2026-11-11). It changes nothing there; the NA preset button puts it back to the saved NA choice.\n    if values.ldpu and not values.exaDpsSupport then\n        values.exaDpsSupport = true\n        cfg.dirty = true\n    end\n    -- The NA mit sheet plan ([Mit] reactions) on or off, styled like the presets (the user, 2026-11-08): the one in use drawn green.\n    GUI:Text(\"Mitigation\")\n    for i, choice in ipairs({ \"NA\", \"Off\" }) do\n        if i > 1 then GUI:SameLine() end\n        local on = choice == \"NA\"\n        local lit = values.mitOn == on\n        if lit then\n            GUI:PushStyleColor(GUI.Col_Button, 0.15, 0.55, 0.2, 1)\n            GUI:PushStyleColor(GUI.Col_ButtonHovered, 0.2, 0.65, 0.25, 1)\n        end\n        if GUI:Button(choice .. \"##TopMit\") and values.mitOn ~= on then\n            values.mitOn = on\n            cfg.dirty = true\n        end\n        if lit then GUI:PopStyleColor(2) end\n    end\n    -- Like Frog Draws' \"Quick style\": every mechanic's guide as arrows or as tethers. Lit when they all match.\n    GUI:Text(\"Quick style\")\n    for i, style in ipairs({ \"Arrow\", \"Tether\" }) do\n        if i > 1 then GUI:SameLine() end\n        local all = true\n        for _, key in ipairs(cfg.STYLE_KEYS) do\n            if values[key] ~= style then all = false end\n        end\n        if all then\n            GUI:PushStyleColor(GUI.Col_Button, 0.15, 0.55, 0.2, 1)\n            GUI:PushStyleColor(GUI.Col_ButtonHovered, 0.2, 0.65, 0.25, 1)\n        end\n        if GUI:Button((style == \"Arrow\" and \"All arrows\" or \"All tethers\") .. \"##TopStyle\") then\n            for _, key in ipairs(cfg.STYLE_KEYS) do values[key] = style end\n            cfg.dirty = true\n        end\n        if all then GUI:PopStyleColor(2) end\n    end\n    GUI:Spacing()\n    GUI:PushItemWidth(170)\n    for _, section in ipairs(cfg.sections) do\n        if GUI:CollapsingHeader(section[1]) then\n            GUI:Indent()\n            for _, row in ipairs(section[2]) do\n                local value, changed\n                if row[3] == nil then\n                    value, changed = GUI:Checkbox(row[2], values[row[1]])\n                elseif row[3] == \"style\" then\n                    -- Frog Draws' per-mechanic style: Arrow or Tether.\n                    local items = { \"Arrow\", \"Tether\" }\n                    local current = values[row[1]] == \"Tether\" and 2 or 1\n                    local picked = GUI:Combo(row[2], current, items)\n                    if picked ~= current and items[picked] then value, changed = items[picked], true end\n                elseif row[3] == \"choice\" then\n                    local items = row[4]\n                    local current = 1\n                    for i, item in ipairs(items) do\n                        if item == values[row[1]] then current = i end\n                    end\n                    local picked = GUI:Combo(row[2], current, items)\n                    if picked ~= current and items[picked] then value, changed = items[picked], true end\n                else\n                    value, changed = GUI:SliderFloat(row[2], values[row[1]], row[3], row[4], row[5])\n                end\n                if changed then\n                    values[row[1]] = value\n                    cfg.dirty = true\n                end\n            end\n            GUI:Unindent()\n            GUI:Spacing()\n        end\n    end\n    GUI:PopItemWidth()\n    GUI:Spacing()\n    if GUI:Button(\"Reset to defaults\") then\n        for key, default in pairs(cfg.defaults) do\n            values[key] = default\n        end\n        cfg.dirty = true\n    end\n    -- Callout text-to-speech on or off, one click from the bottom of the window.\n    GUI:SameLine()\n    if GUI:Button(values.tts and \"TTS: On###TopTts\" or \"TTS: Off###TopTts\") then\n        values.tts = not values.tts\n        cfg.dirty = true\n    end\n    -- Every callout (text and speech) on or off, beside TTS (the user, 2026-11-08).\n    GUI:SameLine()\n    if GUI:Button(values.calloutOn and \"Callouts: On###TopCallouts\" or \"Callouts: Off###TopCallouts\") then\n        values.calloutOn = not values.calloutOn\n        cfg.dirty = true\n    end\nend\n-- Save once a slider is released rather than on every drag step.\nif cfg.dirty and not GUI:IsAnyItemActive() then\n    cfg.dirty = false\n    FileSave(cfg.path, values)\nend\nGUI:End()\nif open == false then\n    data.topLooperOptionsClosed = true\nend\nself.used = true\n",
