				conditions = 
				{
				},
				eventType = 4,
				loop = true,
				mechanicTime = 230.9,
				name = "[Synergy] Marker",
				timeRange = true,
				timelineIndex = 35,
				timerEndOffset = 18,
				timerStartOffset = 2,
				uuid = "93b03ff8-545d-8b25-a844-5b905fe02a21",
