		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P2 Party Synergy: static spread spots after the clones' cleaves, for every shape, with the eye as north. Then the knockback spots,\n-- with the Omega M in the row of 3 clones as north.\n-- Both of my shape's spots are marked. The arrow goes to my side's, by the flex rule: each pair splits left and right by the\n-- conga (HRMTTMRH), earlier on the left. On the knockback it goes to my group once [Synergy] Flex knows it.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topSynergy\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = { shape = s and t >= (s.lastTime or 0) and s.shape or nil }\n    data.topSynergy = s\nend\ns.lastTime = t\ns.lastClock = Now()\nif not values.synSpots and not values.synKnock then\n    s.spots = nil\n    self.used = true\n    return\nend\n\nif not s.initialized then\n    s.initialized = true\n    s.warned = {}\n    s.FROM, s.TO = 241.4, 248.1\n    -- Discharger lands at 254.9 and pushes about 13y. The Spotlight stacks land at 259.1 and the clones' Efficient Bladework at 259.3.\n    s.KNOCK_AT, s.KNOCK_END, s.PUSH = 254.9, 259.35, 13\n    -- Where the party starts the knockback, from the centre. The landings match today's logs: about 16 on Mid and 18.5 on Remote.\n    s.KNOCK_START = { mid = 3, far = 5.5 }\n    s.MID_GLITCH, s.FAR_GLITCH = 3427, 3428\n    s.NAMES = { [416] = \"Circle\", [417] = \"Triangle\", [418] = \"Square\", [419] = \"Cross\" }\n    -- The user's Splatoon presets: this far to the side of the eye's line, and this far from the eye, which stands at r=45.\n    local function fromEye(side, along)\n        local ahead = 45 - along\n        return { math.deg(math.atan2(side, ahead)), math.sqrt(side * side + ahead * ahead) }\n    end\n    -- Bearing with the eye as north, and radius. Minus is left of the eye, seen from the middle.\n    s.LAYOUT = {\n        mid = {\n            [419] = { fromEye(-11, 30), fromEye(11, 30) },\n            [418] = { fromEye(-11, 40), fromEye(11, 40) },\n            [416] = { fromEye(-11, 50), fromEye(11, 50) },\n            [417] = { fromEye(-11, 60), fromEye(11, 60) },\n        },\n        -- The \"far (right flip)\" preset's left side: Cross, Square, Circle, Triangle from the eye. The right side is the user's\n        -- order (2026-11-08): Triangle, Square, Circle, Cross from the eye. The preset's positive offX is the left side here.\n        far = {\n            [419] = { fromEye(-12, 30), fromEye(12, 60) },\n            [418] = { fromEye(-18.5, 40), fromEye(18.5, 40) },\n            [416] = { fromEye(-18.5, 50), fromEye(18.5, 50) },\n            [417] = { fromEye(-12, 60), fromEye(12, 30) },\n        },\n    }\n    -- Elemental (ffxiv.tuufless.com/elemental/top/02_omega_mf, images 04a/04b): the same distances, shapes ○ × ▽ □ from the eye;\n    -- on Remote the right group swaps ○ and □.\n    s.LAYOUT_ELEMENTAL = {\n        mid = {\n            [416] = { fromEye(-11, 30), fromEye(11, 30) },\n            [419] = { fromEye(-11, 40), fromEye(11, 40) },\n            [417] = { fromEye(-11, 50), fromEye(11, 50) },\n            [418] = { fromEye(-11, 60), fromEye(11, 60) },\n        },\n        far = {\n            [416] = { fromEye(-12, 30), fromEye(12, 60) },\n            [419] = { fromEye(-18.5, 40), fromEye(18.5, 40) },\n            [417] = { fromEye(-18.5, 50), fromEye(18.5, 50) },\n            [418] = { fromEye(-12, 60), fromEye(12, 30) },\n        },\n    }\n    -- Mana (lodestone blog 5536808): Elemental's slots; Mid ○ × △ □ both sides, Far left ○ × △ □ and right □ △ × ○.\n    s.LAYOUT_MANA = {\n        mid = s.LAYOUT_ELEMENTAL.mid,\n        far = {\n            [416] = { fromEye(-12, 30), fromEye(12, 60) },\n            [419] = { fromEye(-18.5, 40), fromEye(18.5, 50) },\n            [417] = { fromEye(-18.5, 50), fromEye(18.5, 40) },\n            [418] = { fromEye(-12, 60), fromEye(12, 30) },\n        },\n    }\n    -- Elemental groups (Mana's too: left H1 MT D1 D3, \"adjust bottom to top\"): light party 1 (H1 MT D1 D3) on the left, 2 on the right. A group with two of a shape sends the lower\n    -- (Healer > Tank > Melee > Ranged) across.\n    s.ELEMENTAL_G1 = { H1 = true, T1 = true, M1 = true, R1 = true }\n    s.ELEMENTAL_ORDER = { H1 = 1, T1 = 2, M1 = 3, R1 = 4, H2 = 1, T2 = 2, M2 = 3, R2 = 4 }\n    function s.elementalSide(mySlot, partnerSlot)\n        local mine = s.ELEMENTAL_G1[mySlot] and \"left\" or \"right\"\n        local theirs = s.ELEMENTAL_G1[partnerSlot] and \"left\" or \"right\"\n        if mine ~= theirs then return mine end\n        if s.ELEMENTAL_ORDER[mySlot] < s.ELEMENTAL_ORDER[partnerSlot] then return mine end\n        return mine == \"left\" and \"right\" or \"left\"\n    end\n    -- LDPU (toolbox 502396712985961, steps 4, 8, 9): Mid is NA's B-P-O-G (× □ ○ △) from the eye. On Remote the left column is\n    -- B-P-O-G and the right column G-P-O-B (△ □ ○ × from the eye; the user, 2026-11-10), about 12-13y off the eye's line.\n    s.LAYOUT_LDPU = {\n        mid = s.LAYOUT.mid,\n        far = {\n            [419] = { fromEye(-12, 30), fromEye(12, 60) },\n            [418] = { fromEye(-13, 40), fromEye(13, 40) },\n            [416] = { fromEye(-13, 50), fromEye(13, 50) },\n            [417] = { fromEye(-12, 60), fromEye(12, 30) },\n        },\n    }\n    -- LDPU groups: the west column T H M R (MT H1 M1 R1) on the left, the east column on the right, north to south; of two of a\n    -- shape in one column, the southern one adjusts across.\n    s.LDPU_ORDER = { T1 = 1, H1 = 2, M1 = 3, R1 = 4, T2 = 1, H2 = 2, M2 = 3, R2 = 4 }\n    function s.ldpuSide(mySlot, partnerSlot)\n        local mine = s.ELEMENTAL_G1[mySlot] and \"left\" or \"right\"\n        local theirs = s.ELEMENTAL_G1[partnerSlot] and \"left\" or \"right\"\n        if mine ~= theirs then return mine end\n        if s.LDPU_ORDER[mySlot] < s.LDPU_ORDER[partnerSlot] then return mine end\n        return mine == \"left\" and \"right\" or \"left\"\n    end\n    s.drawRing = TensorCore.getCachedDrawer(nil, nil, 0x44FFFFFF, 0xFFFFFFFF, 2)\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n    s.drawArrow = cfg.styledArrow(\"stSyn\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.CONGA = { H1 = 1, R1 = 2, M1 = 3, T1 = 4, T2 = 5, M2 = 6, R2 = 7, H2 = 8 }\n\n    -- My side of the spread, as [Synergy] Flex splits pairs: of the two players with my shape, the earlier in the conga goes left.\n    function s.spreadSide(me)\n        local flex = data.topSynergyFlex\n        if s.shape == nil or flex == nil or flex.shapes == nil then return nil end\n        local Roster = AnyoneCore and AnyoneCore.Roster\n        local view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\n        if view == nil then\n            s.warnOnce(\"roster\", \"no Party Roster: can't tell my side for the arrow\")\n            return nil\n        end\n        local partner\n        for id, shape in pairs(flex.shapes) do\n            if shape == s.shape and id ~= me.id then partner = id end\n        end\n        local mine, theirs = s.CONGA[view.slotOf(me.id)], partner and s.CONGA[view.slotOf(partner)]\n        if mine == nil or theirs == nil then\n            s.warnOnce(\"partner\", \"my shape's partner wasn't found: no arrow\")\n            return nil\n        end\n        if values.elemental or values.mana then return s.elementalSide(view.slotOf(me.id), view.slotOf(partner)) end\n        if values.ldpu then return s.ldpuSide(view.slotOf(me.id), view.slotOf(partner)) end\n        return mine < theirs and \"left\" or \"right\"\n    end\n\n    function s.log(text)\n        d(\"[Synergy] \" .. text)\n        TensorCore.timelineLogToFile(\"[Synergy] \" .. text .. \"\\n\")\n    end\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            s.log(text)\n        end\n    end\n\n    -- The eye sits at r=45, on one of the 8 waymark directions.\n    function s.readEye()\n        for _, e in pairs(TensorCore.entityList(\"contentid=7640\")) do\n            local dx, dz = e.pos.x - 100, e.pos.z - 100\n            if dx * dx + dz * dz > 20 * 20 then\n                return (math.floor((math.deg(math.atan2(dx, -dz)) % 360) / 45 + 0.5) * 45) % 360\n            end\n        end\n    end\n\n    -- The Omega M that stays at r=13 is the middle of the row of 3 clones. Its bearing is the knockback's north.\n    function s.readRow()\n        for _, content in ipairs({ 7633, 7634, 7635 }) do\n            for _, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                local dx, dz = e.pos.x - 100, e.pos.z - 100\n                if Argus.getEntityModel(e) == 15713 and dx * dx + dz * dz > 11 * 11 then\n                    return math.deg(math.atan2(dx, -dz)) % 360\n                end\n            end\n        end\n    end\n\n    -- The guide: the left group goes relative west. The right group goes relative south on Mid and relative east on Remote.\n    function s.updateKnock(t)\n        s.spots = nil\n        if not values.synKnock then return end\n        if s.row == nil then\n            s.row = s.readRow()\n            if s.row == nil then\n                s.warnOnce(\"row\", \"row of 3 clones not found\")\n                return\n            end\n        end\n        local flex = data.topSynergyFlex\n        local mine = flex and flex.group\n        local radius = s.KNOCK_START[s.glitch] + (t >= s.KNOCK_AT and s.PUSH or 0)\n        local function spot(label, side, bearing)\n            local a = math.rad(s.row + bearing)\n            return { label = label, x = 100 + radius * math.sin(a), z = 100 - radius * math.cos(a), mine = mine == side }\n        end\n        s.spots = { spot(\"Left group\", \"left\", -90), spot(\"Right group\", \"right\", s.glitch == \"far\" and 90 or 180) }\n        for _, row in ipairs(s.spots) do\n            if row.mine then s.mySpot = row end\n        end\n    end\n\n    function s.update(me, t)\n        s.mySpot = nil\n        if t < s.FROM or t >= s.KNOCK_END or (t < s.TO and not values.synSpots) then\n            s.spots = nil\n            return\n        end\n        if s.glitch == nil then\n            if TensorCore.hasBuff(me.id, s.MID_GLITCH) then\n                s.glitch = \"mid\"\n            elseif TensorCore.hasBuff(me.id, s.FAR_GLITCH) then\n                s.glitch = \"far\"\n            else\n                s.warnOnce(\"glitch\", \"no Mid or Remote Glitch on me\")\n                return\n            end\n        end\n        if t >= s.TO then\n            s.updateKnock(t)\n            return\n        end\n        if s.eye == nil then\n            s.eye = s.readEye()\n            if s.eye == nil then\n                s.warnOnce(\"eye\", \"Optical Unit not found\")\n                return\n            end\n        end\n        if s.spots == nil then\n            if s.shape == nil then s.warnOnce(\"shape\", \"no shape marker seen on me\") end\n            local spots = {}\n            for shape, rows in pairs((values.elemental and s.LAYOUT_ELEMENTAL or values.ldpu and s.LAYOUT_LDPU or values.mana and s.LAYOUT_MANA or s.LAYOUT)[s.glitch]) do\n                for i, row in ipairs(rows) do\n                    local a = math.rad(s.eye + row[1])\n                    spots[#spots + 1] = { label = s.NAMES[shape], x = 100 + row[2] * math.sin(a), z = 100 - row[2] * math.cos(a),\n                                          mine = shape == s.shape, side = i == 1 and \"left\" or \"right\" }\n                end\n            end\n            s.spots = spots\n            s.log(string.format(\"%.1f %s glitch, eye at %d, my shape %s\", t, s.glitch, s.eye, tostring(s.NAMES[s.shape])))\n        end\n        local side = values.synArrow and s.spreadSide(me)\n        for _, row in ipairs(s.spots) do\n            if row.mine and row.side == side then s.mySpot = row end\n        end\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil then\n    self.used = true\n    return\nend\nlocal clock = Now()\nif s.nextPass == nil or clock >= s.nextPass then\n    s.nextPass = clock + 100\n    s.update(me, t)\nend\nlocal y = me.pos.y\nfor _, spot in ipairs(s.spots or {}) do\n    if spot.mine then\n        s.drawMine:addCircle(spot.x, y, spot.z, 0.8)\n    else\n        s.drawRing:addCircle(spot.x, y, spot.z, 0.6)\n    end\nend\nlocal spot = s.mySpot\nif spot and s.spots and values.synArrow and me.hp.current > 0 then\n    local dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\n    local dist = math.sqrt(dx * dx + dz * dz)\n    if dist > 0.5 then\n        -- Sized like [Lj Draw] Arrow to Black Hole, except it keeps pointing up close.\n        local scale = math.min(1, dist / 15)\n        local near = math.min(1, dist / 3)\n        local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n        s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n            dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n            false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    end\nend\nself.used = true\n",
