		{
			data = 
			{
				actions = 
				{
					
					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P2 Limitless Synergy, tanks (P2 deck slides 30-38): an arrow through the tether, the shielded Omega M and Beyond Defense.\n-- MT (T1) takes the tether counter-clockwise from North, OT (T2) the one clockwise from North. Bring it toward the add, then point it\n-- clockwise at the wall \"4-5 notches\" from the add (30 degrees, the average of the user's tanks in 4 logged pulls). After the busters\n-- both sit max melee in front of the shielded Omega M. Beyond Defense's target (Twice-come Ruin, 2534) rotates around the hitbox\n-- away from the party; the other tank goes into the party in the middle for Pile Pitch.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal REV = \"2026-11-08-style\"\nlocal s = data.topLimitlessTank\nif s == nil or s.rev ~= REV then\n    s = { rev = REV, warned = {} }\n    data.topLimitlessTank = s\n    s.TETHERS_FROM, s.WALL_FROM, s.BUSTER, s.DEFENSE, s.RUIN_BY, s.PITCH = 287.4, 293.0, 295.95, 306.95, 307.9, 310.0\n    s.GRAB_R, s.WALL_R, s.NOTCHES, s.MELEE = 14, 19, 30, 2\n    s.RUIN = 2534\n    s.drawArrow = cfg.styledArrow(\"stLim\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n    s.drawNext = TensorCore.getCachedDrawer(nil, nil, 0x550000FF, 0xFF0000FF, 2)\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            d(\"[Limitless] \" .. text)\n            TensorCore.timelineLogToFile(\"[Limitless] \" .. text .. \"\\n\")\n        end\n    end\n\n    function s.at(bearing, radius)\n        local a = math.rad(bearing)\n        return { x = 100 + radius * math.sin(a), z = 100 - radius * math.cos(a) }\n    end\n\n    -- Counter-clockwise from North is the west half (180-360), clockwise the east half.\n    -- Elemental: MT takes the north tether, ST the south one.\n    function s.myTether(tethers, slot)\n        for _, c in ipairs(tethers) do\n            local first\n            if values.elemental then\n                first = c.bearing > 270 or c.bearing < 90\n            else\n                first = c.bearing > 180 and c.bearing < 360\n            end\n            if (slot == \"T1\" and first) or (slot == \"T2\" and not first) then return c end\n        end\n    end\n\n    -- Elemental (ffxiv.tuufless.com/elemental/top/02_omega_mf, images 02, 04, 05, FAQ): tethers 24.6 degrees clockwise (the\n    -- FAQ's tangent at r=20 from the clone at r=22); after the busters both tanks just outside the boss's hitbox towards the\n    -- shield clone, MT clockwise and ST counter-clockwise of it; the Beyond Defense target runs round to the far side, the other\n    -- stacks with the party in the middle.\n    s.ELEMENTAL_NOTCHES, s.ELEMENTAL_SPREAD = 24.6, 37\n    function s.elementalAround(shield, slot, hit)\n        local e = shield and TensorCore.mGetEntity(shield)\n        if e == nil or e.pos == nil then return nil end\n        local b = math.deg(math.atan2(e.pos.x - 100, 100 - e.pos.z))\n        local r = 6\n        for _, boss in pairs(TensorCore.entityList(\"contentid=7633\")) do\n            if boss.pos and boss.hitradius and (boss.pos.x - 100) ^ 2 + (boss.pos.z - 100) ^ 2 < 4 then r = boss.hitradius end\n        end\n        local bearing = hit and b + 180 or b + (slot == \"T1\" and s.ELEMENTAL_SPREAD or -s.ELEMENTAL_SPREAD)\n        return s.at(bearing, r + 1)\n    end\n\n    -- Max melee in front of the shielded Omega M (it faces the middle), or that far round its side for the Beyond Defense target.\n    function s.aroundShield(shield, turn, me)\n        local e = shield and TensorCore.mGetEntity(shield)\n        if e == nil or e.pos == nil then return nil end\n        local reach = (e.hitradius or 5) + s.MELEE\n        s.warnOnce(\"hitbox\", string.format(\"shielded Omega M at (%.1f,%.1f) facing %.0f, hitbox %.1f\", e.pos.x, e.pos.z,\n            math.deg(e.pos.h), e.hitradius or -1))\n        local h = e.pos.h\n        if turn then\n            -- Away from the party: round to the side I'm already on.\n            local fx, fz = math.sin(h), math.cos(h)\n            local side = (fx * (me.pos.z - e.pos.z) - fz * (me.pos.x - e.pos.x)) >= 0 and -1 or 1\n            h = h + side * math.pi / 2\n        end\n        return { x = e.pos.x + math.sin(h) * reach, z = e.pos.z + math.cos(h) * reach }\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nlocal rec = data.topLimitless\nif not values.limTank or me == nil or me.pos == nil or me.hp.current <= 0 or t < s.TETHERS_FROM or t >= s.PITCH then\n    self.used = true\n    return\nend\nif rec == nil or Now() - rec.at > 40000 then\n    self.used = true\n    return\nend\nif s.seen ~= rec.at then\n    s.seen, s.warned = rec.at, {}\nend\nlocal Roster = AnyoneCore and AnyoneCore.Roster\nlocal view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\nlocal slot = view and view.mySlot()\nif slot ~= \"T1\" and slot ~= \"T2\" then\n    self.used = true\n    return\nend\nlocal mine = s.myTether(rec.tethers, slot)\nlocal spot, nextSpot\nif t < s.BUSTER then\n    if mine == nil then\n        s.warnOnce(\"tether\", string.format(\"%s: my tether clone wasn't seen (%d recorded)\", slot, #rec.tethers))\n    else\n        local wall = s.at(mine.bearing + (values.elemental and s.ELEMENTAL_NOTCHES or s.NOTCHES), s.WALL_R)\n        s.warnOnce(\"plan\", string.format(\"%s: add at %.0f, wall spot at %.0f\", slot, mine.bearing, (mine.bearing + s.NOTCHES) % 360))\n        if t < s.WALL_FROM then\n            spot, nextSpot = s.at(mine.bearing, s.GRAB_R), wall\n        else\n            spot, nextSpot = wall, values.elemental and s.elementalAround(rec.shield, slot, false) or s.aroundShield(rec.shield, false, me)\n        end\n    end\nelseif values.elemental then\n    local hit = t >= s.DEFENSE and TensorCore.hasBuff(me.id, s.RUIN)\n    if t >= s.RUIN_BY and not hit then\n        spot = { x = 100, z = 100 }\n    else\n        spot = s.elementalAround(rec.shield, slot, hit)\n    end\n    if spot == nil then s.warnOnce(\"shield\", \"the shielded Omega M wasn't seen\") end\nelseif t < s.DEFENSE then\n    spot = s.aroundShield(rec.shield, false, me)\n    if spot == nil then s.warnOnce(\"shield\", \"the shielded Omega M wasn't seen\") end\nelse\n    if TensorCore.hasBuff(me.id, s.RUIN) then\n        spot = s.aroundShield(rec.shield, true, me)\n    elseif t < s.RUIN_BY then\n        -- Twice-come Ruin lands about 0.7s after Beyond Defense: hold until it would have.\n        spot = s.aroundShield(rec.shield, false, me)\n    else\n        spot = { x = 100, z = 100 }\n    end\nend\nif spot == nil then\n    self.used = true\n    return\nend\nlocal y = me.pos.y\ns.drawMine:addCircle(spot.x, y, spot.z, 0.8)\nif nextSpot then s.drawNext:addCircle(nextSpot.x, y, nextSpot.z, 0.8) end\nlocal dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\nlocal dist = math.sqrt(dx * dx + dz * dz)\nif dist > 0.5 then\n    -- Sized like [Lj Draw] Arrow to Black Hole, except it keeps pointing up close.\n    local scale = math.min(1, dist / 15)\n    local near = math.min(1, dist / 3)\n    local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n    s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n        dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n        false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\nend\nself.used = true\n",
							name = "Draw Tank Tether Arrow",
							uuid = "ba6cca73-e553-5b3c-a1db-964bf327a145",
							version = 2.1,
						},
					},
				},
				conditions = 
				{
				},
				eventType = 12,
				loop = true,
				mechanicTime = 282.4,
				name = "[Limitless] Tank Arrow",
				timeRange = true,
