						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P3 Hello, World, from the \"P3 - Final Omega\" guide: clockspots, then the loop Christmas > Defamation > Blue > Stack through 4 Patches.\n-- Every spot comes from the towers. My role and rot come from my debuffs, read fresh for each Patch.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topHello\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = {}\n    data.topHello = s\nend\ns.lastTime = t\ns.lastClock = Now()\nif not values.helSpots and not values.helArrow then\n    s.spots = nil\n    self.used = true\n    return\nend\n\nif not s.initialized then\n    s.initialized = true\n    s.warned = {}\n    s.towers = s.towers or {}\n    s.patches = {}\n    s.CLOCK = { T1 = 0, R2 = 45, H2 = 90, M2 = 135, T2 = 180, M1 = 225, H1 = 270, R1 = 315 }\n    s.LINE = { \"H1\", \"R1\", \"M1\", \"T1\", \"T2\", \"M2\", \"R2\", \"H2\" }\n    s.CLOCK_R = 10.5\n    -- The Hello, World raidwide (31573) lands at 441.19-441.58 in the logged pulls.\n    s.CLOCK_END = 441.6\n    s.TOWER_R = 5\n    s.HIT_AFTER = 10.05\n    s.END = 550.1\n    s.ACTIVE = { { 3525, \"Defamation\" }, { 3524, \"Stack\" }, { 3529, \"Christmas\" }, { 3530, \"Blue\" } }\n    s.SMELL = { { 3437, \"Defamation\" }, { 3436, \"Stack\" }, { 3503, \"Christmas\" }, { 3441, \"Blue\" } }\n    s.RED, s.BLUE, s.RED_SMELL, s.BLUE_SMELL = 3526, 3429, 3438, 3439\n    s.CHRISTMAS_TETHER, s.BLUE_TETHER = 3529, 3530\n    s.drawArrow = cfg.styledArrow(\"stHel\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawRing = TensorCore.getCachedDrawer(nil, nil, 0x44FFFFFF, 0xFFFFFFFF, 2)\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n\n    function s.log(text)\n        d(\"[Hello] \" .. text)\n        TensorCore.timelineLogToFile(\"[Hello] \" .. text .. \"\\n\")\n    end\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            s.log(text)\n        end\n    end\n\n    function s.at(bearing, radius)\n        local a = math.rad(bearing)\n        return 100 + radius * math.sin(a), 100 - radius * math.cos(a)\n    end\n\n    function s.signed(from, to)\n        return (to - from + 180) % 360 - 180\n    end\n\n    function s.partyIDs(me)\n        local ids = { me.id }\n        for id in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            if id ~= me.id then ids[#ids + 1] = id end\n        end\n        return ids\n    end\n\n    -- Of these debuffs, the one with the least time left: a player also holds the debuffs for their later roles, so a fixed order\n    -- read a Blue tether as Christmas whenever Christmas came later (11:23 on 2026-11-07, Patch 1).\n    function s.soonest(id, rows)\n        local best, bestLeft\n        for _, row in ipairs(rows) do\n            local buff = TensorCore.getBuff(id, row[1])\n            if buff then\n                local left = buff.duration or 999\n                if bestLeft == nil or left < bestLeft then best, bestLeft = row[2], left end\n            end\n        end\n        return best\n    end\n\n    function s.roleOf(id)\n        return s.soonest(id, s.ACTIVE) or s.soonest(id, s.SMELL)\n    end\n\n    -- The rot I hold wins over one still to come.\n    function s.rotOf(id)\n        return s.soonest(id, { { s.RED, \"red\" }, { s.BLUE, \"blue\" } }) or s.soonest(id, { { s.RED_SMELL, \"red\" }, { s.BLUE_SMELL, \"blue\" } })\n    end\n\n    -- Every Hello World debuff a player has, with its time left, for checking the reading against a real pull.\n    function s.debuffText(id)\n        local parts = {}\n        local rows = { { s.RED, \"red rot\" }, { s.BLUE, \"blue rot\" }, { s.RED_SMELL, \"red later\" }, { s.BLUE_SMELL, \"blue later\" } }\n        for _, list in ipairs({ s.ACTIVE, s.SMELL, rows }) do\n            for _, row in ipairs(list) do\n                local buff = TensorCore.getBuff(id, row[1])\n                if buff then parts[#parts + 1] = string.format(\"%d %s %.1f\", row[1], row[2], buff.duration or -1) end\n            end\n        end\n        local e = TensorCore.mGetEntity(id)\n        return string.format(\"%s: %s\", e and e.name or tostring(id), #parts > 0 and table.concat(parts, \", \") or \"none\")\n    end\n\n    function s.hasActiveRot(id)\n        return TensorCore.hasBuff(id, s.RED) or TensorCore.hasBuff(id, s.BLUE)\n    end\n\n    -- Who's who at the start of a Patch. It stays fixed, because debuffs change hands the moment the Patch lands.\n    function s.readPatch(me, number, row, t)\n        local p = s.patches[number]\n        if p == nil then\n            p = { number = number, start = row.start, hit = row.start + s.HIT_AFTER, roles = {}, rots = {} }\n            s.patches[number] = p\n            for _, id in ipairs(s.partyIDs(me)) do\n                s.log(string.format(\"%.1f Patch %d debuffs, %s\", t, number, s.debuffText(id)))\n            end\n        end\n        for _, id in ipairs(s.partyIDs(me)) do\n            if p.roles[id] == nil then p.roles[id] = s.roleOf(id) end\n            if p.rots[id] == nil then p.rots[id] = s.rotOf(id) end\n        end\n        if p.role == nil then\n            p.role = p.roles[me.id]\n            if p.role then s.log(string.format(\"%.1f Patch %d: %s, rot %s\", t, number, p.role, tostring(p.rots[me.id]))) end\n        end\n        if p.defamColor == nil then\n            for id, role in pairs(p.roles) do\n                if p.rots[id] then\n                    if role == \"Defamation\" then p.defamColor = p.rots[id] end\n                    if role == \"Stack\" and p.defamColor == nil then p.defamColor = p.rots[id] == \"red\" and \"blue\" or \"red\" end\n                end\n            end\n        end\n        return p\n    end\n\n    -- The pair's spots, one per tower. \"toward\" is degrees towards the other tower of the same colour.\n    function s.pairSpots(towers, toward, radius)\n        local rows = {}\n        for i = 1, 2 do\n            local other = towers[3 - i]\n            local sign = s.signed(towers[i], other) > 0 and 1 or -1\n            local x, z = s.at(towers[i] + sign * toward, radius)\n            rows[i] = { x = x, z = z, bearing = towers[i] + sign * toward, tower = towers[i] }\n        end\n        return rows\n    end\n\n    function s.layout(p, row)\n        local defam = p.defamColor == \"red\" and row.red or row.blue\n        local stack = p.defamColor == \"red\" and row.blue or row.red\n        local out = { Defamation = s.pairSpots(defam, -5, 13) }\n        if p.number < 4 then\n            out.Stack = s.pairSpots(stack, 15, 12)\n            out.Christmas = s.pairSpots(defam, -28, 13)\n            out.Blue = s.pairSpots(stack, 30, 10.5)\n        else\n            out.Stack = s.pairSpots(stack, 24, 12.5)\n            -- Patch 4: all the tethers between the Stacks, around the corner the two towers share.\n            local tether = s.pairSpots(stack, 37, 11.5)\n            out.Christmas, out.Blue = tether, tether\n        end\n        return out\n    end\n\n    function s.dist(e, spot)\n        return math.sqrt((e.pos.x - spot.x) ^ 2 + (e.pos.z - spot.z) ^ 2)\n    end\n\n    function s.mates(me, p, role)\n        local rows = {}\n        for id, other in pairs(p.roles) do\n            if other == role and id ~= me.id then\n                local e = TensorCore.mGetEntity(id)\n                if e and e.pos then rows[#rows + 1] = e end\n            end\n        end\n        return rows\n    end\n\n    -- The tower closest to me, with my partner in mind: whichever split is the shorter walk for the pair. It keeps its choice\n    -- unless the other is at least 2y better, and stops changing 3s before the hit.\n    function s.pick(me, p, rows, t)\n        local mate = s.mates(me, p, p.role)[1]\n        local cost = {}\n        for i = 1, 2 do\n            cost[i] = s.dist(me, rows[i]) + (mate and s.dist(mate, rows[3 - i]) or 0)\n        end\n        if p.choice == nil then\n            p.choice = cost[1] <= cost[2] and 1 or 2\n        elseif t < p.hit - 3 and cost[3 - p.choice] + 2 < cost[p.choice] then\n            p.choice = 3 - p.choice\n        end\n        return p.choice\n    end\n\n    function s.rotsInPlace(p, row)\n        local count = 0\n        for id, role in pairs(p.roles) do\n            if role == \"Defamation\" or role == \"Stack\" then\n                local e = TensorCore.mGetEntity(id)\n                local towers = p.rots[id] == \"red\" and row.red or row.blue\n                local here = false\n                for _, bearing in ipairs(towers) do\n                    if e and e.pos then\n                        local x, z = s.at(bearing, 14)\n                        if s.dist(e, { x = x, z = z }) <= s.TOWER_R + 1 then here = true end\n                    end\n                end\n                if not here then return false end\n                count = count + 1\n            end\n        end\n        return count == 4\n    end\n\n    function s.closest(me, list)\n        local best, bestDist\n        for _, e in ipairs(list) do\n            local dist = s.dist(me, { x = e.pos.x, z = e.pos.z })\n            if bestDist == nil or dist < bestDist then best, bestDist = e, dist end\n        end\n        return best\n    end\n\n    function s.standing(me, label)\n        return { label = label, x = me.pos.x, z = me.pos.z, mine = true }\n    end\n\n    -- Where the deck has me for the steps after a Patch lands.\n    function s.afterHit(me, p, t, spot)\n        local since = t - p.hit\n        local role = p.role\n        local last = p.number == 4\n        if role == \"Defamation\" or role == \"Stack\" then\n            if since < 1 or TensorCore.hasBuff(me.id, s.RED) or TensorCore.hasBuff(me.id, s.BLUE) then\n                return { label = \"Stay until your rot goes\", x = spot.x, z = spot.z, mine = true }\n            end\n            return nil\n        end\n        if last then\n            if role == \"Blue\" then\n                if since < 2.6 then return { label = \"Wait for the vuln\", x = spot.x, z = spot.z, mine = true } end\n                local target = s.closest(me, s.mates(me, p, \"Stack\"))\n                if since < 6 and TensorCore.hasBuff(me.id, s.BLUE_TETHER) and target then\n                    return { label = \"Break: to the Stack\", x = target.pos.x, z = target.pos.z, mine = true }\n                end\n            elseif since < 3 then\n                return { label = \"Stay\", x = spot.x, z = spot.z, mine = true }\n            end\n            return nil\n        end\n        if since < 1 then\n            return { label = \"Wait for the vuln\", x = spot.x, z = spot.z, mine = true }\n        end\n        if p.gotRot == nil and s.hasActiveRot(me.id) then\n            p.gotRot = t\n            s.log(string.format(\"%.1f picked up rot\", t))\n        end\n        if not p.gotRot and since < 5.5 then\n            local target = s.closest(me, s.mates(me, p, role == \"Blue\" and \"Stack\" or \"Defamation\"))\n            if target then\n                return { label = \"Take the rot\", x = target.pos.x, z = target.pos.z, mine = true }\n            end\n        end\n        if role == \"Christmas\" and TensorCore.hasBuff(me.id, s.CHRISTMAS_TETHER) and since < 7 then\n            if since < 3.2 then return s.standing(me, \"Wait: Blue breaks first\") end\n            local mate = s.mates(me, p, \"Christmas\")[1]\n            if mate then\n                return { label = \"Break: to the other Christmas\", x = mate.pos.x, z = mate.pos.z, mine = true }\n            end\n        end\n        return nil\n    end\n\n    function s.clockSpots(me)\n        local Roster = AnyoneCore and AnyoneCore.Roster\n        local view = Roster and cfg.rosterView(Roster, me)\n        local mine = view and view.mySlot()\n        if view == nil then s.warnOnce(\"roster\", \"no Party Roster: can't mark my clockspot\") end\n        local spots, mySpot = {}, nil\n        for _, name in ipairs(s.LINE) do\n            local x, z = s.at(s.CLOCK[name], s.CLOCK_R)\n            local spot = { label = name, x = x, z = z, mine = name == mine }\n            spots[#spots + 1] = spot\n            if spot.mine then mySpot = spot end\n        end\n        return spots, mySpot\n    end\n\n    function s.currentPatch(t)\n        local number\n        for i = 1, 4 do\n            local row = s.towers[i]\n            if row and t >= row.start and #row.red == 2 and #row.blue == 2 then number = i end\n        end\n        return number\n    end\n\n    function s.update(me, t)\n        if t >= s.END then\n            s.spots, s.mySpot = nil, nil\n            return\n        end\n        local number = s.currentPatch(t)\n        if number == nil then\n            if t < s.CLOCK_END then\n                s.spots, s.mySpot = s.clockSpots(me)\n            else\n                s.spots, s.mySpot = nil, nil\n            end\n            if t >= 457 then s.warnOnce(\"towers\", \"no towers seen for Patch 1\") end\n            return\n        end\n        local row = s.towers[number]\n        local p = s.readPatch(me, number, row, t)\n        if p.role == nil then\n            s.warnOnce(\"role\" .. number, \"Patch \" .. number .. \": no Hello World debuff on me\")\n        end\n        if p.defamColor == nil then\n            s.warnOnce(\"color\" .. number, \"Patch \" .. number .. \": can't tell which towers the Defamations take\")\n            s.spots, s.mySpot = nil, nil\n            return\n        end\n        local rows = s.layout(p, row)\n\n        local spots, mySpot = {}, nil\n        local choice\n        if p.role then\n            choice = s.pick(me, p, rows[p.role], t)\n        end\n        if t < p.hit + 1 then\n            -- Labels: on Patch 4 the Christmas and Blue spots are the same two places.\n            local order = { \"Defamation\", \"Stack\", \"Christmas\", \"Blue\" }\n            for _, role in ipairs(order) do\n                if not (p.number == 4 and role == \"Blue\") then\n                    local label = (p.number == 4 and role == \"Christmas\") and \"Tethers\" or role\n                    local isMine = role == p.role or (p.number == 4 and role == \"Christmas\" and p.role == \"Blue\")\n                    for i = 1, 2 do\n                        local spot = rows[role][i]\n                        spots[#spots + 1] = { label = label, x = spot.x, z = spot.z, mine = isMine }\n                    end\n                end\n            end\n        end\n        if choice then\n            local target = rows[p.role][choice]\n            if t < p.hit then\n                local tether = p.role == \"Christmas\" or p.role == \"Blue\"\n                if tether and not p.ready then\n                    if t >= p.hit - 3.5 or s.rotsInPlace(p, row) then\n                        p.ready = true\n                    end\n                end\n                -- Tethers wait in the middle until the rots are in, with no draw pulling them there.\n                if not (tether and not p.ready) then\n                    mySpot = { label = p.role, x = target.x, z = target.z, mine = true }\n                end\n            else\n                mySpot = s.afterHit(me, p, t, target)\n                if mySpot and t >= p.hit + 1 then spots[#spots + 1] = mySpot end\n            end\n        end\n        s.spots, s.mySpot = spots, mySpot\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil then\n    self.used = true\n    return\nend\nlocal clock = Now()\nif s.nextPass == nil or clock >= s.nextPass then\n    s.nextPass = clock + 100\n    s.update(me, t)\nend\n\nlocal y = me.pos.y\n-- The towers, stack, defamation and rot draws were removed at the user's request (2026-11-08).\nif values.helSpots then\n    for _, spot in ipairs(s.spots or {}) do\n        if spot.mine then\n            s.drawMine:addCircle(spot.x, y, spot.z, 0.8)\n        else\n            s.drawRing:addCircle(spot.x, y, spot.z, 0.6)\n        end\n    end\nend\nlocal spot = s.mySpot\nif spot and values.helArrow and me.hp.current > 0 then\n    local dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\n    local dist = math.sqrt(dx * dx + dz * dz)\n    if dist > 0.5 then\n        -- Sized like [Lj Draw] Arrow to Black Hole, except it keeps pointing up close.\n        local scale = math.min(1, dist / 15)\n        local near = math.min(1, dist / 3)\n        local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n        s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n            dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n            false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    end\nend\nself.used = true\n",
