					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- Towers: 31583 red, 31584 blue. Four casters start together for each Patch, about 10s before it lands.\nlocal s = data.topHello\nif s == nil then\n    s = {}\n    data.topHello = s\nend\nlocal e = TensorCore.mGetEntity(eventArgs.entityID)\nif e and e.pos then\n    local t = TensorReactions_CurrentTimer\n    local patch, best = 1, 999\n    for i, start in ipairs({ 455.4, 476.5, 497.4, 518.7 }) do\n        if math.abs(t - start) < best then patch, best = i, math.abs(t - start) end\n    end\n    s.towers = s.towers or {}\n    local row = s.towers[patch]\n    if row == nil then\n        row = { start = t, red = {}, blue = {} }\n        s.towers[patch] = row\n    end\n    local list = eventArgs.spellID == 31583 and row.red or row.blue\n    if #list < 2 then\n        list[#list + 1] = math.deg(math.atan2(e.pos.x - 100, 100 - e.pos.z)) % 360\n    end\nend\nself.used = true\n",
