lkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P5 Run: Dynamis Delta, from the \"P5 - Delta... in greater detail\" guide. Draws every spot for the current step\n-- and marks mine. Spots are written with Beetle relative west and Final Omega relative east: x east, z south.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topDelta\n-- A new pull: the timer drops a lot or frames stopped. Timeline syncs can step back a second or more mid-mechanic.\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = {}\n    data.topDelta = s\nend\ns.lastTime = t\ns.lastClock = Now()\nif not values.delSpots and not values.delArrow and not values.delBreak and not values.delSwap and not values.delMonitor then\n    s.spots = nil\n    s.breakAlert, s.swapAlert, s.monitorAlert = nil, nil, nil\n    self.used = true\n    return\nend\n\nif not s.initialized then\n    s.initialized = true\n    s.turns = s.turns or {}\n    s.warned = {}\n    s.stage = 0\n    s.spots = {}\n    s.BLUE_TETHER, s.GREEN_TETHER = 201, 200\n    s.MONITOR_RIGHT, s.MONITOR_LEFT = 3452, 3453\n    s.MONITOR_FACING = math.cos(math.rad(15))\n    s.drawArrow = cfg.styledArrow(\"stDel\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawRing = TensorCore.getCachedDrawer(nil, nil, 0x44FFFFFF, 0xFFFFFFFF, 2)\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n    s.drawLine = TensorCore.getCachedDrawer(nil, nil, 0xFF00FFFF, 0xFF00FFFF, 2)\n    s.drawBeamGood = TensorCore.getCachedDrawer(nil, nil, 0x3300FF00, 0xFF00FF00, 2)\n    s.drawBeamBad = TensorCore.getCachedDrawer(nil, nil, 0x440000FF, 0xFF0000FF, 2)\n    s.drawBeamOther = TensorCore.getCachedDrawer(nil, nil, 0x2200A5FF, 0xFF00A5FF, 2)\n    s.drawBossHalf = TensorCore.getCachedDrawer(nil, nil, 0x220000FF, 0x880000FF, 2)\n    -- Gold rings on a pair's fists when they're the same colour (the fist swap reminder, for everyone to see).\n    s.drawFistMatch = TensorCore.getCachedDrawer(nil, nil, 0x5500D7FF, 0xFF00D7FF, 3)\n\n    function s.log(text)\n        d(\"[Delta] \" .. text)\n        TensorCore.timelineLogToFile(\"[Delta] \" .. text .. \"\\n\")\n    end\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            s.log(text)\n        end\n    end\n\n    function s.find(content, model)\n        for id, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n            if Argus.getEntityModel(e) == model then\n                return id, e\n            end\n        end\n    end\n\n    -- Rotates clockwise so that relative west lands on Beetle.\n    function s.setAnchor(beetle)\n        local bearing = math.deg(math.atan2(beetle.pos.x - 100, 100 - beetle.pos.z))\n        local a = math.rad(bearing - 270)\n        s.cos, s.sin = math.cos(a), math.sin(a)\n    end\n\n    function s.toWorld(x, z)\n        return 100 + x * s.cos - z * s.sin, 100 + z * s.cos + x * s.sin\n    end\n\n    function s.toRel(x, z)\n        local dx, dz = x - 100, z - 100\n        return dx * s.cos + dz * s.sin, dz * s.cos - dx * s.sin\n    end\n\n    function s.relOf(id)\n        local e = TensorCore.mGetEntity(id)\n        if e and e.pos then\n            return s.toRel(e.pos.x, e.pos.z)\n        end\n    end\n\n    function s.readPairs()\n        local blue, green, seen = {}, {}, {}\n        for source, list in pairs(Argus.getCurrentTethers()) do\n            for _, tether in ipairs(list) do\n                if (tether.type == s.BLUE_TETHER or tether.type == s.GREEN_TETHER) and not seen[source] and not seen[tether.targetid] then\n                    seen[source], seen[tether.targetid] = true, true\n                    local bucket = tether.type == s.BLUE_TETHER and blue or green\n                    bucket[#bucket + 1] = source\n                    bucket[#bucket + 1] = tether.targetid\n                end\n            end\n        end\n        if #blue ~= 4 or #green ~= 4 then\n            return\n        end\n        s.blue, s.green = blue, green\n        s.players = {}\n        for _, list in ipairs({ blue, green }) do\n            for _, id in ipairs(list) do s.players[#s.players + 1] = id end\n        end\n        s.log(\"pairs read\")\n    end\n\n    -- As the Splatoon script does: sort a colour by angle from its boss and split it into two sides. On each side, whoever is nearer the centre is inner.\n    function s.readSides(list, mob)\n        local mobX, mobZ = s.toRel(mob.pos.x, mob.pos.z)\n        local rows = {}\n        for _, id in ipairs(list) do\n            local x, z = s.relOf(id)\n            if x == nil then return nil end\n            rows[#rows + 1] = { id = id, angle = math.atan2(z - mobZ, math.abs(x - mobX)), dist = x * x + z * z }\n        end\n        table.sort(rows, function(a, b) return a.angle < b.angle end)\n        local function split(a, b)\n            if a.dist <= b.dist then return a.id, b.id end\n            return b.id, a.id\n        end\n        local innerN, outerN = split(rows[1], rows[2])\n        local innerS, outerS = split(rows[3], rows[4])\n        return { innerN = innerN, outerN = outerN, innerS = innerS, outerS = outerS }\n    end\n\n    function s.readRoles(beetle, omega)\n        local blue, green = s.readSides(s.blue, beetle), s.readSides(s.green, omega)\n        if blue == nil or green == nil then return false end\n        s.sides = { blue = blue, green = green }\n        s.roles = {}\n        for colour, row in pairs(s.sides) do\n            s.roles[row.innerN], s.roles[row.innerS] = { colour, \"Inner\" }, { colour, \"Inner\" }\n            s.roles[row.outerN], s.roles[row.outerS] = { colour, \"Outer\" }, { colour, \"Outer\" }\n        end\n        return true\n    end\n\n    -- The fists lock everyone's role and side. An inner player whose fist matches their outer partner's swaps to the other side.\n    function s.readFists(beetle, omega)\n        local fists = {}\n        for _, content in ipairs({ 7696, 7697 }) do\n            for _, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                fists[#fists + 1] = { id = e.id, x = e.pos.x, z = e.pos.z, colour = content }\n            end\n        end\n        if #fists < 8 or not s.readRoles(beetle, omega) then\n            return false\n        end\n        local function fistOf(id)\n            local e = TensorCore.mGetEntity(id)\n            local best, bestDist\n            if e and e.pos then\n                for _, fist in ipairs(fists) do\n                    local dist = (fist.x - e.pos.x) ^ 2 + (fist.z - e.pos.z) ^ 2\n                    if best == nil or dist < bestDist then\n                        best, bestDist = fist, dist\n                    end\n                end\n            end\n            return best\n        end\n        s.side = {}\n        s.fistMatch, s.fistNotice = {}, {}\n        for _, row in pairs(s.sides) do\n            local innerN, innerS = row.innerN, row.innerS\n            local outerFistN, innerFistN = fistOf(row.outerN), fistOf(innerN)\n            local outerFistS, innerFistS = fistOf(row.outerS), fistOf(innerS)\n            local matchN = outerFistN ~= nil and innerFistN ~= nil and outerFistN.colour == innerFistN.colour\n            local matchS = outerFistS ~= nil and innerFistS ~= nil and outerFistS.colour == innerFistS.colour\n            if matchN or matchS then\n                innerN, innerS = innerS, innerN\n                s.swapped = s.swapped or {}\n                s.swapped[innerN], s.swapped[innerS] = true, true\n                -- The user (2026-11-10): show it to everyone. The outers of this colour are told too, and the matching fists get rings.\n                s.fistNotice[row.outerN], s.fistNotice[row.outerS] = true, true\n                if matchN then\n                    s.fistMatch[#s.fistMatch + 1] = outerFistN.id\n                    s.fistMatch[#s.fistMatch + 1] = innerFistN.id\n                end\n                if matchS then\n                    s.fistMatch[#s.fistMatch + 1] = outerFistS.id\n                    s.fistMatch[#s.fistMatch + 1] = innerFistS.id\n                end\n            end\n            s.side[row.outerN], s.side[row.outerS] = \"N\", \"S\"\n            s.side[innerN], s.side[innerS] = \"N\", \"S\"\n        end\n        return true\n    end\n\n    function s.roleOf(id)\n        local role = s.roles and s.roles[id]\n        if role then return role[1], role[2] end\n    end\n\n    function s.anyHas(a, b)\n        for _, id in ipairs(s.players or {}) do\n            if TensorCore.hasBuff(id, a) or (b and TensorCore.hasBuff(id, b)) then\n                return true\n            end\n        end\n        return false\n    end\n\n    -- Elemental \"Kinda Awk\" (ffxiv.tuufless.com/elemental/top/05_run_dynamis_delta, images 01-09). Blue lines by the Beetle (long\n    -- tether outside, short inside), green lines by Final Omega; at the fists the inner blue lines up beside the outer and the inner\n    -- green stacks on the outer; arms as NA; monitor hits at the side walls; Near baits at the Beetle-side intercard.\n    function s.elementalStage(stage, key, add, me, m)\n        if stage == 1 then\n            add(\"Outer Blue N\", -14, -8, key == \"blueOuterN\")\n            add(\"Outer Blue S\", -14, 8, key == \"blueOuterS\")\n            add(\"Inner Blue N\", -8.4, -4, key == \"blueInnerN\")\n            add(\"Inner Blue S\", -8.4, 4, key == \"blueInnerS\")\n            add(\"Inner Green N\", 7.2, -8, key == \"greenInnerN\")\n            add(\"Inner Green S\", 7.2, 8, key == \"greenInnerS\")\n            add(\"Outer Green N\", 13, -8, key == \"greenOuterN\")\n            add(\"Outer Green S\", 13, 8, key == \"greenOuterS\")\n            return true\n        elseif stage == 2 then\n            add(\"Outer Blue N\", -14, -8, key == \"blueOuterN\")\n            add(\"Outer Blue S\", -14, 8, key == \"blueOuterS\")\n            add(\"Inner Blue N\", -14.4, -4.4, key == \"blueInnerN\")\n            add(\"Inner Blue S\", -14.4, 4.4, key == \"blueInnerS\")\n            add(\"Green Stack N\", 13, -8, key == \"greenInnerN\" or key == \"greenOuterN\")\n            add(\"Green Stack S\", 13, 8, key == \"greenInnerS\" or key == \"greenOuterS\")\n            return true\n        elseif stage == 3 then\n            add(\"Blue Stack N\", -14.4, -4.4, key == \"blueInnerN\" or key == \"blueOuterN\")\n            add(\"Blue Stack S\", -14.4, 4.4, key == \"blueInnerS\" or key == \"blueOuterS\")\n            add(\"Green Stack N\", 13, -8, key == \"greenInnerN\" or key == \"greenOuterN\")\n            add(\"Green Stack S\", 13, 8, key == \"greenInnerS\" or key == \"greenOuterS\")\n            return true\n        end\n        return false\n    end\n\n    -- OCE (materiaraiding.com/ultimate/top, image top-delta): both colours line up along their boss's wall, measured from the\n    -- image. At the fists the greens stack and the inner blue holds (the outer blue joins it once its tether breaks); an inner\n    -- whose fist matches swaps with the other inner, as NA. Arms, monitors and Hello World are the same as NA.\n    function s.oceStage(stage, key, add)\n        if stage == 1 then\n            add(\"Outer Blue N\", -14, -8.4, key == \"blueOuterN\")\n            add(\"Outer Blue S\", -14, 8.4, key == \"blueOuterS\")\n            add(\"Inner Blue N\", -12, -2.9, key == \"blueInnerN\")\n            add(\"Inner Blue S\", -12, 2.9, key == \"blueInnerS\")\n            add(\"Inner Green N\", 10.7, -9, key == \"greenInnerN\")\n            add(\"Inner Green S\", 10.7, 9, key == \"greenInnerS\")\n            add(\"Outer Green N\", 13.4, -9, key == \"greenOuterN\")\n            add(\"Outer Green S\", 13.4, 9, key == \"greenOuterS\")\n            return true\n        elseif stage == 2 then\n            add(\"Outer Blue N\", -14, -8.4, key == \"blueOuterN\")\n            add(\"Outer Blue S\", -14, 8.4, key == \"blueOuterS\")\n            add(\"Inner Blue N\", -12, -2.9, key == \"blueInnerN\")\n            add(\"Inner Blue S\", -12, 2.9, key == \"blueInnerS\")\n            add(\"Green Stack N\", 12, -9, key == \"greenInnerN\" or key == \"greenOuterN\")\n            add(\"Green Stack S\", 12, 9, key == \"greenInnerS\" or key == \"greenOuterS\")\n            return true\n        elseif stage == 3 then\n            add(\"Blue Stack N\", -12, -2.9, key == \"blueInnerN\" or key == \"blueOuterN\")\n            add(\"Blue Stack S\", -12, 2.9, key == \"blueInnerS\" or key == \"blueOuterS\")\n            add(\"Green Stack N\", 12, -9, key == \"greenInnerN\" or key == \"greenOuterN\")\n            add(\"Green Stack S\", 12, 9, key == \"greenInnerS\" or key == \"greenOuterS\")\n            return true\n        end\n        return false\n    end\n\n    -- LDPU (toolbox 955389449416761, steps 4-12, measured): the outer blue pair under the Beetle, both inner pairs a little in\n    -- from their walls, the outer greens on the 1/2 waymarks. At the fists the inner blues step just above/below the outer pair\n    -- and the greens stack on the waymarks; the blues then stack on the outer pair. The arms (stage 4) and the Monitor lines\n    -- (stage 5) are handled in those stages.\n    function s.ldpuStage(stage, key, add)\n        if stage == 1 then\n            add(\"Outer Blue N\", -14, -2, key == \"blueOuterN\")\n            add(\"Outer Blue S\", -14, 2, key == \"blueOuterS\")\n            add(\"Inner Blue N\", -8.9, -4.3, key == \"blueInnerN\")\n            add(\"Inner Blue S\", -8.9, 4.3, key == \"blueInnerS\")\n            add(\"Inner Green N\", 6.5, -4.3, key == \"greenInnerN\")\n            add(\"Inner Green S\", 6.5, 4.3, key == \"greenInnerS\")\n            add(\"Outer Green N\", 10, -10, key == \"greenOuterN\")\n            add(\"Outer Green S\", 10, 10, key == \"greenOuterS\")\n            return true\n        elseif stage == 2 then\n            add(\"Outer Blue N\", -14, -2, key == \"blueOuterN\")\n            add(\"Outer Blue S\", -14, 2, key == \"blueOuterS\")\n            add(\"Inner Blue N\", -14, -6, key == \"blueInnerN\")\n            add(\"Inner Blue S\", -14, 6, key == \"blueInnerS\")\n            add(\"Green Stack N\", 10, -10, key == \"greenInnerN\" or key == \"greenOuterN\")\n            add(\"Green Stack S\", 10, 10, key == \"greenInnerS\" or key == \"greenOuterS\")\n            return true\n        elseif stage == 3 then\n            add(\"Blue Stack N\", -14, -2, key == \"blueInnerN\" or key == \"blueOuterN\")\n            add(\"Blue Stack S\", -14, 2, key == \"blueInnerS\" or key == \"blueOuterS\")\n            add(\"Green Stack N\", 10, -10, key == \"greenInnerN\" or key == \"greenOuterN\")\n            add(\"Green Stack S\", 10, 10, key == \"greenInnerS\" or key == \"greenOuterS\")\n            return true\n        end\n        return false\n    end\n\n    -- Mana \"Hamukatsu\" (lodestone blog 5536808 cheat sheet, measured): the blue that keeps its tether (outer, ②) by the Beetle,\n    -- the one that breaks naturally (inner, ①) further north/south; the green pairs side by side near the N/S walls. Only the\n    -- setup is shown; fists onward follow NA (arms as NA: ② the Beetle arms, ① the middle).\n    function s.manaStageOne(key, add)\n        add(\"Outer Blue N\", -12.1, -4.9, key == \"blueOuterN\")\n        add(\"Outer Blue S\", -12.1, 4.9, key == \"blueOuterS\")\n        add(\"Inner Blue N\", -8.6, -7.5, key == \"blueInnerN\")\n        add(\"Inner Blue S\", -8.6, 7.5, key == \"blueInnerS\")\n        add(\"Inner Green N\", 5.2, -9.9, key == \"greenInnerN\")\n        add(\"Inner Green S\", 5.2, 9.9, key == \"greenInnerS\")\n        add(\"Outer Green N\", 9.1, -9.9, key == \"greenOuterN\")\n        add(\"Outer Green S\", 9.1, 9.9, key == \"greenOuterS\")\n    end\n\n    function s.stageOne(key, add)\n        -- Outer Blue on the Beetle-side intercard waymarks, like Outer Green on theirs (the user, 2026-11-08).\n        add(\"Outer Blue N\", -10, -10, key == \"blueOuterN\")\n        add(\"Outer Blue S\", -10, 10, key == \"blueOuterS\")\n        add(\"Inner Blue N\", -4, -3.7, key == \"blueInnerN\")\n        add(\"Inner Blue S\", -4, 3.7, key == \"blueInnerS\")\n        add(\"Inner Green N\", 4.2, -7.2, key == \"greenInnerN\")\n        add(\"Inner Green S\", 4.2, 7.2, key == \"greenInnerS\")\n        add(\"Outer Green N\", 10, -10, key == \"greenOuterN\")\n        add(\"Outer Green S\", 10, 10, key == \"greenOuterS\")\n    end\n\n    -- The fists: Outer Blue on the Beetle-side intercard waymarks, the short-tether Inner Blue between them in the same column\n    -- (the user, 2026-11-08, from their party in the 12:32 pull's replay).\n    function s.stageTwo(key, add)\n        add(\"Outer Blue N\", -10, -10, key == \"blueOuterN\")\n        add(\"Outer Blue S\", -10, 10, key == \"blueOuterS\")\n        add(\"Inner Blue N\", -10, -2, key == \"blueInnerN\")\n        add(\"Inner Blue S\", -10, 2, key == \"blueInnerS\")\n        add(\"Green Stack N\", 10, -10, key == \"greenInnerN\" or key == \"greenOuterN\")\n        add(\"Green Stack S\", 10, 10, key == \"greenInnerS\" or key == \"greenOuterS\")\n    end\n\n    function s.stageThree(key, add)\n        add(\"Blue Stack N\", -10, -2, key == \"blueInnerN\" or key == \"blueOuterN\")\n        add(\"Blue Stack S\", -10, 2, key == \"blueInnerS\" or key == \"blueOuterS\")\n        add(\"Green Stack N\", 10, -10, key == \"greenInnerN\" or key == \"greenOuterN\")\n        add(\"Green Stack S\", 10, 10, key == \"greenInnerS\" or key == \"greenOuterS\")\n    end\n\n    -- Each baiter stands 3y from their arm at 80 degrees off its facing, which is the bearing shifted 8.6 degrees at r=19.5.\n    function s.stageFour(key, add)\n        if values.elemental then\n            add(\"Inner Blue N\", -5.6, -7.5, key == \"blueInnerN\")\n            add(\"Inner Blue S\", -5.6, 7.5, key == \"blueInnerS\")\n        elseif values.ldpu then\n            -- LDPU: the outer blues (their tether already gone) bait Beyond Defense either side of the middle.\n            add(\"Outer Blue N\", -1.3, -7.5, key == \"blueOuterN\")\n            add(\"Outer Blue S\", -1.3, 7.5, key == \"blueOuterS\")\n        else\n            add(\"Inner Blue N\", 0, -5, key == \"blueInnerN\")\n            add(\"Inner Blue S\", 0, 5, key == \"blueInnerS\")\n        end\n        local arms = {}\n        for _, content in ipairs({ 7637, 7638 }) do\n            for id, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                local x, z = s.toRel(e.pos.x, e.pos.z)\n                local turn = s.turns[id]\n                local bearing = math.deg(math.atan2(x, -z))\n                local name, mineKey, shift\n                local side = z < 0 and \"N\" or \"S\"\n                if x > 5 then\n                    name, mineKey = \"Outer Green \" .. side, \"greenOuter\" .. side\n                elseif x < -5 then\n                    -- LDPU: the still-tethered (inner) blues bait the Beetle-side arms, which pops their tether.\n                    local layer = values.ldpu and \"Inner\" or \"Outer\"\n                    name, mineKey = layer .. \" Blue \" .. side, \"blue\" .. layer .. side\n                else\n                    name, mineKey = \"Inner Green \" .. side, \"greenInner\" .. side\n                end\n                if turn == 156 then shift = -8.6 elseif turn == 157 then shift = 8.6 else shift = 0 end\n                arms[#arms + 1] = { name = name, key = mineKey, bearing = bearing, shift = shift, x = x, side = side }\n            end\n        end\n        -- Every arm is baited on the wall (r=19.5), so its laser goes out of the arena, not across the party. The user's party did\n        -- this for both Outer Green arms when they pointed toward each other (replay of the 22:35 pull, 2026-11-08); the guide's\n        -- \"slightly inside\" (r=17) for that case was dropped at the user's request.\n        for _, arm in ipairs(arms) do\n            local radius = 19.5\n            local a = math.rad(arm.bearing + arm.shift)\n            add(arm.name, radius * math.sin(a), -radius * math.cos(a), key == arm.key)\n        end\n    end\n\n    function s.stageFive(key, add, me, safe)\n        local isBlue = key and key:sub(1, 4) == \"blue\"\n        local ruin = isBlue and TensorCore.hasBuff(me.id, 2534)\n        local monitor = TensorCore.hasBuff(me.id, s.MONITOR_RIGHT) or TensorCore.hasBuff(me.id, s.MONITOR_LEFT)\n        local r = 16 * math.sqrt(0.5)\n        if values.elemental then\n            add(\"Inner Green N\", -7, -17, key == \"greenInnerN\")\n            add(\"Inner Green S\", -7, 17, key == \"greenInnerS\")\n            add(\"Outer Green N\", 6.5, -17, key == \"greenOuterN\")\n            add(\"Outer Green S\", 6.5, 17, key == \"greenOuterS\")\n        elseif values.ldpu then\n            -- LDPU step 12: the greens in two lines near the N/S walls, centre-fist baiters west, Final-fist baiters east.\n            add(\"Inner Green N\", -9.5, -13.3, key == \"greenInnerN\")\n            add(\"Inner Green S\", -9.5, 13.3, key == \"greenInnerS\")\n            add(\"Outer Green N\", 9.7, -13.3, key == \"greenOuterN\")\n            add(\"Outer Green S\", 9.7, 13.3, key == \"greenOuterS\")\n        else\n            add(\"Inner Green N\", -r, -r, key == \"greenInnerN\")\n            add(\"Inner Green S\", -r, r, key == \"greenInnerS\")\n            add(\"Outer Green N\", r, -r, key == \"greenOuterN\")\n            add(\"Outer Green S\", r, r, key == \"greenOuterS\")\n        end\n        if safe then\n            add(\"Pile Pitch\", 0, 2 * safe, isBlue and not ruin and not monitor)\n            add(\"Beyond Defense\", -11, 1 * safe, isBlue and ruin and not monitor)\n            add(\"Monitor\", -1, 4 * safe, isBlue and monitor and not ruin)\n            add(\"Beyond Defense + Monitor\", 7.5, 4 * safe, isBlue and monitor and ruin)\n        end\n    end\n\n    function s.stageSix(key, add, me, m)\n        local unsafe = m > 0 and \"N\" or \"S\"\n        local near = TensorCore.hasBuff(me.id, 3442)\n        local far = TensorCore.hasBuff(me.id, 3443)\n        local isBlue = key and key:sub(1, 4) == \"blue\"\n        local isInnerGreen = key and key:sub(1, 10) == \"greenInner\"\n        local isOuterGreen = key and key:sub(1, 10) == \"greenOuter\"\n        local onUnsafe = key and key:sub(-1) == unsafe\n        add(\"Near World\", -0.2, 6.5 * m, near)\n        add(\"Distant World\", -0.3, 19 * m, far)\n        add(\"Blue Nothings\", 8.5, 15.5 * m, isBlue and not near and not far)\n        if values.elemental then\n            add(\"Near Bait (edge)\", -13.4, 13.4 * m, isInnerGreen and not onUnsafe)\n            add(\"Near Bait (marker)\", -10, 10 * m, isInnerGreen and onUnsafe)\n        else\n            add(\"Near Bait (plant)\", -8.4, 8.4 * m, isInnerGreen and not onUnsafe)\n            add(\"Near Bait (break tether)\", -8.7, 2.4 * m, isInnerGreen and onUnsafe)\n        end\n        add(\"Far Bait (under Beetle)\", -18.9, 1.4 * m, isOuterGreen and onUnsafe)\n        add(\"Far Bait (plant)\", 15.5, 10.7 * m, isOuterGreen and not onUnsafe)\n    end\n\n    -- From the Splatoon script: never break a live tether while anyone still has a Ruin or vulnerability debuff. Live tethers are 225 blue, 224 green.\n    -- Inner blue also holds until the monitors appear, as the script's notes and deck slide 17 say.\n    function s.updateBreak(me)\n        s.breakAlert = nil\n        if not values.delBreak or s.players == nil or me.hp.current <= 0 then return end\n        local live\n        for source, list in pairs(Argus.getCurrentTethers()) do\n            for _, tether in ipairs(list) do\n                if (tether.type == 224 or tether.type == 225) and (source == me.id or tether.targetid == me.id) then\n                    live = tether.type\n                end\n            end\n        end\n        if live == nil then return end\n        local _, layer = s.roleOf(me.id)\n        local unsafe = s.anyHas(2530, 2534) or s.anyHas(2941)\n        local text\n        if live == 225 then\n            if layer == \"Inner\" and s.stage < 4 then unsafe = true end\n            text = \"Break: go far\"\n        elseif (layer == \"Inner\" and s.stage >= 6) or s.stage >= 7 then\n            text = \"Break: go close\"\n        else\n            return\n        end\n        if unsafe then\n            s.breakAlert = { text = \"WAIT: don't break yet\", go = false }\n        else\n            s.breakAlert = { text = text, go = true }\n        end\n    end\n\n    -- From the Splatoon script: my fist matches my outer partner's, so I have to cross. Goes away once I've crossed, or when the tethers go live.\n    function s.updateSwap(me)\n        s.swapAlert = nil\n        if not values.delSwap or s.stage >= 3 or me.hp.current <= 0 then return end\n        if s.fistNotice and s.fistNotice[me.id] then\n            -- An outer whose colour has a same-colour pair: it stays, the two inners cross.\n            s.swapAlert = { text = \"FISTS MATCH: your inners swap sides\", swap = true }\n            return\n        end\n        if s.swapped == nil or not s.swapped[me.id] then return end\n        local _, z = s.relOf(me.id)\n        local want = s.side and s.side[me.id]\n        if z == nil or (want == \"N\" and z < -0.5) or (want == \"S\" and z > 0.5) then return end\n        s.swapAlert = { text = \"SWAP: go to the other side\", swap = true }\n    end\n\n    -- A monitor fires from a player's right or left side. Deck slides 23-26: aim it at the safe side's two greens, and keep the other blue players out of it.\n    function s.shootDir(e, right)\n        local fx, fz = math.sin(e.pos.h or 0), math.cos(e.pos.h or 0)\n        if right then return -fz, fx end\n        return fz, -fx\n    end\n\n    function s.updateMonitor(me, t, key)\n        s.monitors, s.beam, s.faceLine, s.monitorAlert = nil, nil, nil, nil\n        if not values.delMonitor or s.players == nil or s.stage < 3 or s.stage >= 5.5 then return end\n        s.monitors = {}\n        for _, id in ipairs(s.players) do\n            local right = TensorCore.hasBuff(id, s.MONITOR_RIGHT)\n            if right or TensorCore.hasBuff(id, s.MONITOR_LEFT) then\n                s.monitors[#s.monitors + 1] = { id = id, right = right, mine = id == me.id }\n            end\n        end\n        local right = TensorCore.hasBuff(me.id, s.MONITOR_RIGHT)\n        if not right and not TensorCore.hasBuff(me.id, s.MONITOR_LEFT) then return end\n        if me.hp.current <= 0 or (key and key:sub(1, 5) == \"green\") then return end\n        local sideText = right and \"right\" or \"left\"\n        if s.omegaSide == nil then\n            s.monitorAlert = { text = \"MONITOR: fires from your \" .. sideText, swap = true }\n            return\n        end\n        -- The safe side in world terms, and the way to face so my monitor fires at it.\n        local aimX, aimZ = -s.omegaSide * s.sin, s.omegaSide * s.cos\n        s.beam = { x = aimX, z = aimZ, right = right }\n        if right then s.faceLine = { x = aimZ, z = -aimX } else s.faceLine = { x = -aimZ, z = aimX } end\n        if s.stage < 5 then\n            s.monitorAlert = { text = \"MONITOR: fires from your \" .. sideText .. \", face the yellow arrow after the bait\", swap = true }\n            return\n        end\n        local shootX, shootZ = s.shootDir(me, right)\n        if shootX * aimX + shootZ * aimZ < s.MONITOR_FACING then\n            s.monitorAlert = { text = \"MONITOR: turn to the yellow arrow\" }\n            return\n        end\n        -- The other blue players should be stacked behind me by now.\n        if t >= 771 then\n            for _, id in ipairs(s.blue or {}) do\n                local e = id ~= me.id and TensorCore.mGetEntity(id)\n                if e and e.pos and (e.pos.x - me.pos.x) * shootX + (e.pos.z - me.pos.z) * shootZ > 0 then\n                    s.monitorAlert = { text = \"MONITOR: a blue player is in your beam\" }\n                    return\n                end\n            end\n        end\n        s.monitorAlert = { text = (data.topFace and data.topFace.locked) and \"MONITOR: face locked\" or \"MONITOR: facing OK\", go = true }\n    end\n\n    function s.update(me, t)\n        s.updateBreak(me)\n        s.updateSwap(me)\n        local beetleID, beetle = s.find(7695, 15724)\n        local omegaID, omega = s.find(7636, 14669)\n        -- Final Omega leaves after the Monitors, and only the early stages need it.\n        if beetle == nil or (omega == nil and s.stage < 5.5) then\n            if t >= 744 then s.warnOnce(\"anchor\", \"Beetle or Final Omega not found\") end\n            return\n        end\n        if s.cos == nil then\n            s.setAnchor(beetle)\n        end\n        if s.players == nil and t >= 743 then\n            s.readPairs()\n        end\n        if s.side == nil and s.players then\n            -- Until the fists lock it, roles follow where everyone stands right now.\n            s.readRoles(beetle, omega)\n            if t >= 750 then\n                if t < 754 then\n                    s.readFists(beetle, omega)\n                else\n                    s.warnOnce(\"fists\", \"fists were not read, so sides follow where each player stands\")\n                end\n            end\n        end\n\n        -- Stages only move forward: game events first, the times are a fallback.\n        local stage = s.stage\n        if stage < 1 and t >= 743.2 then stage = 1 end\n        if stage < 2 and (s.side or t >= 751.3) then stage = 2 end\n        if stage < 3 and t >= 760.85 then stage = 3 end\n        if stage == 3 and ((t >= 762.5 and s.anyHas(s.MONITOR_RIGHT, s.MONITOR_LEFT)) or t >= 763.6) then\n            stage = 4\n        end\n        if stage == 4 then\n            local casting = t >= 769\n            for _, content in ipairs({ 7637, 7638 }) do\n                for _, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                    if e.castinginfo and e.castinginfo.channelingid == 31600 then casting = true end\n                end\n            end\n            if casting then stage = 5 end\n        end\n        if stage == 5 and (t >= 774.2 or (t >= 773 and not s.anyHas(s.MONITOR_RIGHT, s.MONITOR_LEFT))) then\n            stage = 5.5\n        end\n        if stage == 5.5 and t >= 775 then\n            local channel = beetle.castinginfo and beetle.castinginfo.channelingid\n            if channel == 31637 then s.lineup = 1 elseif channel == 31636 then s.lineup = -1 end\n            if s.lineup then stage = 6 end\n        end\n        if stage == 6 and t >= 780 and (t >= 791 or not s.anyHas(3442, 3443)) then\n            stage = 7\n        end\n        if s.omegaSide == nil and t >= 762 and omega and omega.castinginfo then\n            local channel = omega.castinginfo.channelingid\n            if channel == 31638 then s.omegaSide = 1 elseif channel == 31639 then s.omegaSide = -1 end\n        end\n        if stage ~= s.stage then\n            s.stage = stage\n            s.log(string.format(\"%.1f stage %s\", t, tostring(stage)))\n        end\n\n        local colour, layer = s.roleOf(me.id)\n        local key\n        if colour then\n            local side = s.side and s.side[me.id]\n            if side == nil then\n                local _, z = s.toRel(me.pos.x, me.pos.z)\n                side = z < 0 and \"N\" or \"S\"\n            end\n            key = colour .. layer .. side\n        elseif stage >= 1 then\n            s.warnOnce(\"role\", \"my tether pair is not known\")\n        end\n        local spots = {}\n        local function add(label, x, z, mine)\n            local wx, wz = s.toWorld(x, z)\n            spots[#spots + 1] = { label = label, x = wx, z = wz, mine = mine and true or false }\n        end\n        if values.elemental and s.elementalStage(stage, key, add) then\n            -- Elemental's own steps 1-3.\n        elseif values.oce and s.oceStage(stage, key, add) then\n            -- OCE's own steps 1-3.\n        elseif values.ldpu and s.ldpuStage(stage, key, add) then\n            -- LDPU's own steps 1-3.\n        elseif values.mana and stage == 1 then s.manaStageOne(key, add)\n        elseif stage == 1 then s.stageOne(key, add)\n        elseif stage == 2 then s.stageTwo(key, add)\n        elseif stage == 3 then s.stageThree(key, add)\n        elseif stage == 4 then s.stageFour(key, add)\n        elseif stage == 5 then s.stageFive(key, add, me, s.omegaSide)\n        elseif stage == 6 then s.stageSix(key, add, me, s.lineup)\n        end\n        s.spots = spots\n        s.mySpot = nil\n        for _, spot in ipairs(spots) do\n            if spot.mine then s.mySpot = spot end\n        end\n        s.updateMonitor(me, t, key)\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil then\n    self.used = true\n    return\nend\nlocal clock = Now()\nif s.nextPass == nil or clock >= s.nextPass then\n    s.nextPass = clock + 100\n    s.update(me, t)\nend\n\nlocal y = me.pos.y\nif values.delSpots then\n    for _, spot in ipairs(s.spots or {}) do\n        if spot.mine then\n            s.drawMine:addCircle(spot.x, y, spot.z, 0.8)\n        else\n            s.drawRing:addCircle(spot.x, y, spot.z, 0.6)\n        end\n    end\nend\nif values.delSwap and s.fistMatch and s.stage < 3 then\n    for _, id in ipairs(s.fistMatch) do\n        local fist = TensorCore.mGetEntity(id)\n        if fist and fist.pos then\n            s.drawFistMatch:addCircle(fist.pos.x, fist.pos.y, fist.pos.z, 1.5)\n        end\n    end\nend\nlocal spot = s.mySpot\nif spot and me.hp.current > 0 then\n    if values.delArrow then\n        local dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\n        local dist = math.sqrt(dx * dx + dz * dz)\n        if dist > 0.5 then\n            -- Sized like [Lj Draw] Arrow to Black Hole, except it keeps pointing up close.\n            local scale = math.min(1, dist / 15)\n            local near = math.min(1, dist / 3)\n            local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n            s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n                dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n                false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n        end\n    end\nend\nif values.delMonitor and s.monitors then\n    -- Final Omega's half of the room. Off by default: Anyone's profile draws it too.\n    if values.delBossHalf and s.omegaSide and s.cos then\n        s.drawBossHalf:addRect(100, y, 100, 20, 40, math.atan2(s.omegaSide * s.sin, -s.omegaSide * s.cos))\n    end\n    -- Each monitor player's half of the room, live from where they face. Other players' are off by default.\n    for _, row in ipairs(s.monitors) do\n        local e = (row.mine and me) or (values.delOtherBeams and TensorCore.mGetEntity(row.id)) or nil\n        if e and e.pos and e.hp and e.hp.current > 0 then\n            local shootX, shootZ = s.shootDir(e, row.right)\n            local drawer = s.drawBeamOther\n            if row.mine and s.beam then\n                drawer = (shootX * s.beam.x + shootZ * s.beam.z >= s.MONITOR_FACING) and s.drawBeamGood or s.drawBeamBad\n            end\n            drawer:addRect(e.pos.x, y, e.pos.z, 30, 60, math.atan2(shootX, shootZ))\n        end\n    end\n    -- Which way to face, from my feet so it's readable while I move.\n    if s.faceLine and me.hp.current > 0 then\n        s.drawLine:addArrow(me.pos.x, y, me.pos.z, math.atan2(s.faceLine.x, s.faceLine.z), 3, 0.5, 1.5, 1.5, false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    end\nend\nself.used = true\n",
							name = "Solve Delta",
