							conditionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\nlocal ROLES = { Phys = true }\n-- [Mit] gate: true when mitigation is on and my role uses this row of the mit sheet. ROLES is set above for each reaction.\n-- M1 and M2 come from my Party Roster slot. Casters (BLM, SMN, RDM, PCT) are \"Caster\", or \"Fake\" in an M1/M2 slot.\n-- Physical ranged (BRD, MCH, DNC) are \"Phys\" whatever their slot.\nif not cfg.values.mitOn then return false end\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.hp == nil or me.hp.current <= 0 then return false end\nlocal Roster = AnyoneCore and AnyoneCore.Roster\nlocal view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\nlocal slot = view and view.mySlot()\nlocal CASTER = { [25] = true, [27] = true, [35] = true, [42] = true }\nlocal PHYS = { [23] = true, [31] = true, [38] = true }\nlocal role\nif CASTER[me.job] then\n    role = (slot == \"M1\" or slot == \"M2\") and \"Fake\" or \"Caster\"\nelseif PHYS[me.job] then\n    role = \"Phys\"\nelseif slot == \"M1\" or slot == \"M2\" then\n    role = slot\nend\nreturn role ~= nil and ROLES[role] == true\n",
							name = "Phys gate",
							uuid = "d68e9e8c-f830-1525-9248-2f98bc6536cc",
							version = 3,
						},
					},
