					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P5 Run: Dynamis Sigma, from the \"P5 - Sigma... in greater detail\" guide. Draws every spot for the current step and\n-- marks mine. Part 1 uses the line-up wall as north, the towers use the absolute waymarks, Part 2 uses Omega F as north.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topSigma\n-- A new pull: the timer drops a lot or frames stopped. Timeline syncs can step back a second or more mid-mechanic.\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = {}\n    data.topSigma = s\nend\ns.lastTime = t\ns.lastClock = Now()\nif not values.sigSpots and not values.sigArrow then\n    s.spots = nil\n    self.used = true\n    return\nend\n\nif not s.initialized then\n    s.initialized = true\n    s.shapes = s.shapes or {}\n    s.prey = s.prey or {}\n    s.warned = {}\n    s.spots = {}\n    s.slots = {}\n    -- BPOG, from the wall towards the middle.\n    s.ROWS = { { 419, \"Cross\", 18.4 }, { 418, \"Square\", 16 }, { 416, \"Circle\", 13 }, { 417, \"Triangle\", 10.6 } }\n    -- Elemental (ffxiv.tuufless.com/elemental/top/05_run_dynamis_sigma, image 01): ○ × ▽ □ from the top, lined up between the arms\n    -- south of the middle (negative = away from Omega M), columns 3.6 either side.\n    s.ROWS_ELEMENTAL = { { 416, \"Circle\", -3 }, { 419, \"Cross\", -5.7 }, { 417, \"Triangle\", -8.4 }, { 418, \"Square\", -10.8 } }\n    -- Mana \"Wingman\" (lodestone blog 5536808): ○ × △ □ from Omega M, at NA's distances from the wall.\n    s.ROWS_MANA = { { 416, \"Circle\", 18.4 }, { 419, \"Cross\", 16 }, { 417, \"Triangle\", 13 }, { 418, \"Square\", 10.6 } }\n    function s.rows() return values.elemental and s.ROWS_ELEMENTAL or values.mana and s.ROWS_MANA or s.ROWS end\n    s.MID_GLITCH, s.FAR_GLITCH = 3427, 3428\n    s.WAYMARKS = { \"A\", \"1\", \"B\", \"2\", \"C\", \"3\", \"D\", \"4\" }\n    s.PARTNER = { A = \"C\", C = \"A\", B = \"D\", D = \"B\", [\"1\"] = \"3\", [\"3\"] = \"1\", [\"2\"] = \"4\", [\"4\"] = \"2\" }\n    -- Only Attack 2/3 are interchangeable: the user removed the 1/4 flex (2026-11-08), so 1 and 4 keep their own spots.\n    s.PAIR = { [2] = 3, [3] = 2 }\n    -- The guide's tower cheat sheet, clockwise from the pattern's north.\n    s.SHEET = {\n        mid = { { \"2\" }, { \"D\", \"4\" }, { \"C\" }, { \"B\" }, { \"A\", \"3\" }, { \"1\" } },\n        far = { { \"1\", \"2\" }, { \"D\" }, { \"4\", \"C\" }, { \"B\", \"3\" }, { \"A\" } },\n    }\n    -- The spinner turns 9 degrees every 0.577 seconds for 13 steps from its first shot.\n    s.SHOT_AT, s.SHOT_RATE, s.SHOT_MAX = 870.7, 9 / 0.577, 117\n    s.drawArrow = cfg.styledArrow(\"stSig\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawRing = TensorCore.getCachedDrawer(nil, nil, 0x44FFFFFF, 0xFFFFFFFF, 2)\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n\n    function s.log(text)\n        d(\"[Sigma] \" .. text)\n        TensorCore.timelineLogToFile(\"[Sigma] \" .. text .. \"\\n\")\n    end\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            s.log(text)\n        end\n    end\n\n    function s.bearingOf(x, z)\n        return math.deg(math.atan2(x - 100, 100 - z)) % 360\n    end\n\n    function s.snap(bearing)\n        return (math.floor(bearing / 45 + 0.5) * 45) % 360\n    end\n\n    -- Relative frame: north points along the given bearing.\n    function s.toWorld(north, x, z)\n        local a = math.rad(north)\n        local c, n = math.cos(a), math.sin(a)\n        return 100 + x * c - z * n, 100 + z * c + x * n\n    end\n\n    function s.toRel(north, x, z)\n        local a = math.rad(north)\n        local c, n = math.cos(a), math.sin(a)\n        local dx, dz = x - 100, z - 100\n        return dx * c + dz * n, dz * c - dx * n\n    end\n\n    -- Omega M comes in opposite the arms, but only after everyone should already be walking there.\n    function s.findLineUp()\n        local arms, sumX, sumZ = 0, 0, 0\n        for _, content in ipairs({ 7637, 7638 }) do\n            for _, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                if Argus.isEntityVisible(e) then\n                    arms = arms + 1\n                    sumX, sumZ = sumX + e.pos.x - 100, sumZ + e.pos.z - 100\n                end\n            end\n        end\n        if arms == 2 and (sumX ~= 0 or sumZ ~= 0) then\n            s.lineUp = s.snap((math.deg(math.atan2(sumX, -sumZ)) + 180) % 360)\n        end\n        for _, content in ipairs({ 12257, 12258, 7635 }) do\n            for _, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                if Argus.getEntityModel(e) == 15720 and Argus.isEntityVisible(e)\n                    and math.sqrt((e.pos.x - 100) ^ 2 + (e.pos.z - 100) ^ 2) > 15 then\n                    s.lineUp = s.snap(s.bearingOf(e.pos.x, e.pos.z))\n                    s.lineUpFixed = true\n                end\n            end\n        end\n    end\n\n    function s.rowOf(id)\n        local marker = s.shapes[id]\n        for i, row in ipairs(s.rows()) do\n            if row[1] == marker then return i, row end\n        end\n    end\n\n    function s.partnerOf(id)\n        for other, marker in pairs(s.shapes) do\n            if other ~= id and marker == s.shapes[id] then return other end\n        end\n    end\n\n    function s.relX(id)\n        local e = TensorCore.mGetEntity(id)\n        if e and e.pos then\n            local x = s.toRel(s.lineUp, e.pos.x, e.pos.z)\n            return x\n        end\n    end\n\n    -- The guide's prey rules. Each role is a bearing from the line-up wall.\n    function s.solvePrey()\n        local byRow = {}\n        for id, marker in pairs(s.shapes) do\n            byRow[marker] = byRow[marker] or {}\n            table.insert(byRow[marker], id)\n        end\n        local singles, doubles = {}, {}\n        for _, row in ipairs(s.rows()) do\n            local ids = byRow[row[1]]\n            if ids == nil or #ids ~= 2 then return false end\n            local marked = (s.prey[ids[1]] and 1 or 0) + (s.prey[ids[2]] and 1 or 0)\n            if marked == 1 then\n                singles[#singles + 1] = ids\n            elseif marked == 2 then\n                doubles[#doubles + 1] = ids\n            end\n        end\n        if #singles ~= 2 or #doubles ~= 2 then\n            s.warnOnce(\"prey\", \"prey markers aren't two single and two double pairs\")\n            return false\n        end\n        local roles = {}\n        local function single(ids, unmarked, marked)\n            local free, hit = ids[1], ids[2]\n            if s.prey[free] then free, hit = hit, free end\n            roles[free], roles[hit] = unmarked, marked\n        end\n        if values.mana then\n            -- Mana: the single-marker pair nearer Omega M is ① (Nothing NE, marked SW), the other ② (Nothing NW, marked SE).\n            single(singles[1], 45, 225)\n            single(singles[2], 315, 135)\n        else\n            single(singles[1], 315, 135)\n            single(singles[2], 45, 225)\n        end\n        -- Facing the wall, the player on the right of the first double goes south.\n        local function byX(ids)\n            local a, b = s.relX(ids[1]) or 0, s.relX(ids[2]) or 0\n            if a <= b then return ids[1], ids[2] end\n            return ids[2], ids[1]\n        end\n        local left, right = byX(doubles[1])\n        roles[left], roles[right] = 0, 180\n        left, right = byX(doubles[2])\n        roles[left], roles[right] = 270, 90\n        s.roles = roles\n        s.log(\"prey solved\")\n        return true\n    end\n\n    function s.readTowers(glitch)\n        local singles, duals = {}, {}\n        local function read(content, into)\n            for _, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                local r = math.sqrt((e.pos.x - 100) ^ 2 + (e.pos.z - 100) ^ 2)\n                if r > 12 and r < 21 then\n                    into[#into + 1] = { x = e.pos.x, z = e.pos.z, bearing = s.bearingOf(e.pos.x, e.pos.z) }\n                end\n            end\n        end\n        read(2013245, singles)\n        read(2013246, duals)\n        local wantS, wantD = 4, 2\n        if glitch == \"far\" then wantS, wantD = 2, 3 end\n        if #singles ~= wantS or #duals ~= wantD then return false end\n        local north\n        if glitch == \"mid\" then\n            -- The two double towers sit either side of the end furthest from the pattern's north.\n            local sx = (duals[1].x - 100) + (duals[2].x - 100)\n            local sz = (duals[1].z - 100) + (duals[2].z - 100)\n            north = (math.deg(math.atan2(sx, -sz)) + 180) % 360\n        else\n            -- North is the isolated double tower.\n            local best, bestGap\n            for i, a in ipairs(duals) do\n                local gap = 1e9\n                for j, b in ipairs(duals) do\n                    if i ~= j then gap = math.min(gap, (a.x - b.x) ^ 2 + (a.z - b.z) ^ 2) end\n                end\n                if best == nil or gap > bestGap then best, bestGap = a, gap end\n            end\n            north = best.bearing\n        end\n        local all = {}\n        for _, list in ipairs({ singles, duals }) do\n            for _, tower in ipairs(list) do\n                tower.offset = (tower.bearing - north + 1) % 360\n                all[#all + 1] = tower\n            end\n        end\n        table.sort(all, function(a, b) return a.offset < b.offset end)\n        local sheet = s.SHEET[glitch]\n        local tower = {}\n        for i, labels in ipairs(sheet) do\n            for _, label in ipairs(labels) do tower[label] = all[i] end\n        end\n        -- Mid stands in the centre; Far stands at the edge diagonally away from their partner.\n        local spots = {}\n        for label, at in pairs(tower) do\n            local x, z = at.x, at.z\n            if glitch == \"far\" then\n                local other = tower[s.PARTNER[label]]\n                local dx, dz = at.x - other.x, at.z - other.z\n                local len = math.sqrt(dx * dx + dz * dz)\n                x, z = at.x + dx / len * 2.5, at.z + dz / len * 2.5\n            end\n            spots[label] = { x = x, z = z }\n        end\n        s.towerSpots = spots\n        s.log(string.format(\"towers read, pattern north %.1f\", north))\n        return true\n    end\n\n    function s.findOmegaF()\n        for _, content in ipairs({ 12258, 12257, 7635, 7634 }) do\n            for id, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                if Argus.getEntityModel(e) == 15720 and Argus.isEntityVisible(e)\n                    and math.sqrt((e.pos.x - 100) ^ 2 + (e.pos.z - 100) ^ 2) > 5 then\n                    s.omegaF = id\n                    s.fNorth = s.snap(s.bearingOf(e.pos.x, e.pos.z))\n                end\n            end\n        end\n    end\n\n    -- Flags 49 mean blade feet. The cast settles it once it starts.\n    function s.isBlades()\n        local e = s.omegaF and TensorCore.mGetEntity(s.omegaF)\n        if e == nil then return false end\n        local _, flags = Argus.getEntityTransforms(e)\n        local blades = flags == 49\n        local cast = e.castinginfo and e.castinginfo.channelingid\n        if cast == 31533 then\n            blades = false\n        elseif cast == 31530 or cast == 31531 or cast == 31532 then\n            blades = true\n        end\n        return blades\n    end\n\n    -- Which of the two Binds I am: the one further along the spinner's direction follows it, the other waits.\n    function s.bindFollows(me, dir)\n        local other\n        for _, id in pairs(s.partyIDs or {}) do\n            local e = TensorCore.mGetEntity(id)\n            if e and e.id ~= me.id and (e.marker == 6 or e.marker == 7 or e.marker == 8) then other = e end\n        end\n        local mineX = s.toRel(s.fNorth, me.pos.x, me.pos.z)\n        if other == nil or other.pos == nil then\n            return mineX * dir < 0\n        end\n        local otherX = s.toRel(s.fNorth, other.pos.x, other.pos.z)\n        return mineX * dir < otherX * dir\n    end\n\n    -- Attack 2/3 are interchangeable: the pair takes whichever split means less total walking, then I keep my choice.\n    function s.pickSlot(me, mark, spotLow, spotHigh)\n        if s.slots[mark] then return s.slots[mark] end\n        local pair = s.PAIR[mark]\n        if pair == nil then return mark end\n        local low, high = math.min(mark, pair), math.max(mark, pair)\n        local function dist(e, spot)\n            return math.sqrt((e.pos.x - spot.x) ^ 2 + (e.pos.z - spot.z) ^ 2)\n        end\n        local other\n        for _, id in ipairs(s.partyIDs or {}) do\n            local e = TensorCore.mGetEntity(id)\n            if e and e.id ~= me.id and e.marker == pair and e.pos then other = e end\n        end\n        local lowCost, highCost = dist(me, spotLow), dist(me, spotHigh)\n        if other then\n            lowCost, highCost = lowCost + dist(other, spotHigh), highCost + dist(other, spotLow)\n        end\n        local slot = mark\n        if math.abs(lowCost - highCost) >= 0.01 then\n            slot = lowCost < highCost and low or high\n        end\n        s.slots[mark] = slot\n        s.log(string.format(\"sign %d takes the Attack %d spot, partner %s\", mark, slot, other and \"seen\" or \"not seen\"))\n        return slot\n    end\n\n    function s.polar(north, bearing, r)\n        local a = math.rad(bearing)\n        local x, z = s.toWorld(north, r * math.sin(a), -r * math.cos(a))\n        return { x = x, z = z }\n    end\n\n    function s.update(me, t)\n        if s.glitch == nil then\n            if TensorCore.hasBuff(me.id, s.MID_GLITCH) then\n                s.glitch = \"mid\"\n            elseif TensorCore.hasBuff(me.id, s.FAR_GLITCH) then\n                s.glitch = \"far\"\n            end\n            if s.glitch then s.log(\"glitch \" .. s.glitch) end\n        end\n        if not s.lineUpFixed and t >= 824 and t < 845 then\n            s.findLineUp()\n        end\n        local party = {}\n        for id in pairs(s.shapes) do party[#party + 1] = id end\n        s.partyIDs = party\n        local preyCount = 0\n        for _ in pairs(s.prey) do preyCount = preyCount + 1 end\n        if s.roles == nil and preyCount == 6 and #party == 8 and s.lineUp then\n            s.solvePrey()\n        end\n        if t >= 837 and s.roles == nil then\n            s.warnOnce(\"noRoles\", string.format(\"no spread role: %d shapes, %d prey\", #party, preyCount))\n        end\n        if s.myWay == nil and t >= 845.1 and t < 852 and s.lineUp then\n            local bearing = s.roles and s.roles[me.id]\n            if bearing then\n                bearing = (bearing + s.lineUp) % 360\n            else\n                bearing = s.snap(s.bearingOf(me.pos.x, me.pos.z))\n            end\n            s.myWay = s.WAYMARKS[math.floor(bearing / 45 + 0.5) % 8 + 1]\n            s.log(\"resolved at waymark \" .. s.myWay)\n        end\n        if s.towerSpots == nil and s.glitch and t >= 847 and t < 856 then\n            s.readTowers(s.glitch)\n        end\n        if t >= 858 and s.fNorth == nil then\n            s.findOmegaF()\n        end\n\n        local spots = {}\n        local function add(label, x, z, mine)\n            spots[#spots + 1] = { label = label, x = x, z = z, mine = mine and true or false }\n        end\n        local function addRel(north, label, x, z, mine)\n            local wx, wz = s.toWorld(north, x, z)\n            add(label, wx, wz, mine)\n        end\n        local function addPolar(north, label, bearing, r, mine)\n            local a = math.rad(bearing)\n            addRel(north, label, r * math.sin(a), -r * math.cos(a), mine)\n        end\n\n        if t >= 824.8 and t < 834.9 and s.lineUp then\n            -- Stage 1: the line-up. Left and right aren't assigned, so I take the side I'm already on against my partner.\n            -- Keep it until we've clearly crossed, so the arrow doesn't flip while we're stacked or walking together.\n            local myRow = s.rowOf(me.id)\n            local partner = s.partnerOf(me.id)\n            local mineX = s.relX(me.id)\n            local otherX = partner and s.relX(partner)\n            if mineX and otherX then\n                local gap = mineX - otherX\n                if s.myLeft == nil then\n                    s.myLeft = gap <= 0\n                elseif s.myLeft and gap > 1 then\n                    s.myLeft = false\n                elseif not s.myLeft and gap < -1 then\n                    s.myLeft = true\n                end\n            end\n            local half = values.elemental and 3.6 or 2\n            for i, row in ipairs(s.rows()) do\n                addRel(s.lineUp, row[2] .. \" L\", -half, -row[3], i == myRow and s.myLeft == true)\n                addRel(s.lineUp, row[2] .. \" R\", half, -row[3], i == myRow and s.myLeft == false)\n            end\n        elseif t >= 834.9 and t < 845.15 and s.lineUp then\n            -- Stage 2: spread on the prey rules. Far at the wall, Mid a step in from the waymark.\n            local r = s.glitch == \"far\" and 19 or 12\n            local mine = s.roles and s.roles[me.id]\n            addPolar(s.lineUp, \"N: 1st double\", 0, r, mine == 0)\n            addPolar(s.lineUp, \"S: 1st double\", 180, r, mine == 180)\n            addPolar(s.lineUp, \"W: 2nd double\", 270, r, mine == 270)\n            addPolar(s.lineUp, \"E: 2nd double\", 90, r, mine == 90)\n            local first, second = \"1st\", \"2nd\"\n            if values.mana then first, second = \"2nd\", \"1st\" end\n            addPolar(s.lineUp, \"NW: \" .. first .. \" single unmarked\", 315, r, mine == 315)\n            addPolar(s.lineUp, \"SE: \" .. first .. \" single marked\", 135, r, mine == 135)\n            addPolar(s.lineUp, \"NE: \" .. second .. \" single unmarked\", 45, r, mine == 45)\n            addPolar(s.lineUp, \"SW: \" .. second .. \" single marked\", 225, r, mine == 225)\n        elseif t >= 845.15 and t < 856.45 then\n            -- Stage 3: collapse, then knockback start spots, then the towers.\n            if s.towerSpots == nil then\n                add(\"Middle\", 100, 100, true)\n            else\n                local knocked = t >= 852.45\n                local seen = {}\n                for label, spot in pairs(s.towerSpots) do\n                    local x, z = spot.x, spot.z\n                    if not knocked then\n                        local dx, dz = x - 100, z - 100\n                        local r = math.sqrt(dx * dx + dz * dz)\n                        local inner = math.max(1, r - 13)\n                        x, z = 100 + dx / r * inner, 100 + dz / r * inner\n                    end\n                    local key = string.format(\"%.1f/%.1f\", x, z)\n                    if seen[key] then\n                        seen[key].label = seen[key].label .. \" / \" .. label\n                        seen[key].mine = seen[key].mine or label == s.myWay\n                    else\n                        seen[key] = { label = label, x = x, z = z, mine = label == s.myWay }\n                        spots[#spots + 1] = seen[key]\n                    end\n                end\n            end\n        elseif t >= 856.45 and t < 858.8 then\n            add(\"Middle\", 100, 100, true)\n        elseif values.mana and t >= 858.8 and t < 882.7 and s.fNorth then\n            -- Mana (lodestone blog cheat sheet, Dynamis Jumps): Attack 1-5 by macro, plus one player with nothing. Start: 1-3 and\n            -- Hello Far by Omega F, 4, 5, the blank and Hello Near away from her. Final (spin dir +1 shown): 1/2 the NW/NE walls,\n            -- 3/4 the W/E walls (mirrored with the spin), Hello Far 9.5 out on 4's side, Hello Near 7.5 south, 5 and the blank at the\n            -- south wall either side of the line.\n            local north, dir = s.fNorth, s.spin\n            if (me.marker or 0) ~= 0 then s.sign = me.marker end\n            local marker = s.sign or 0\n            local near = TensorCore.hasBuff(me.id, 3442)\n            local far = TensorCore.hasBuff(me.id, 3443)\n            local blank = marker == 0 and not near and not far\n            local isNorth = marker == 1 or marker == 2 or marker == 3 or far\n            if dir == nil or t < 873.75 then\n                if dir == nil and t >= 861.5 then s.warnOnce(\"spin\", \"spinner direction not seen\") end\n                local off = dir and 22.5 * dir or 0\n                addPolar(north, \"North group\", off, dir and 19 or 17, isNorth)\n                addPolar(north, \"South group\", 180 + off, dir and 19 or 17, not isNorth)\n            else\n                addPolar(north, \"1: NW wall\", 315, 18, marker == 1)\n                addPolar(north, \"2: NE wall\", 45, 18, marker == 2)\n                addPolar(north, \"3: Distant bait\", -90 * dir, 18, marker == 3)\n                addPolar(north, \"4: Distant bait\", 90 * dir, 18, marker == 4)\n                addPolar(north, \"Hello Far\", 90 * dir, 9.5, far)\n                addPolar(north, \"Hello Near\", 180, 7.5, near)\n                addPolar(north, \"5: south wall\", 196, 17, marker == 5)\n                addPolar(north, \"Blank: south wall\", 166, 17, blank)\n            end\n        elseif t >= 858.8 and t < 882.7 and s.fNorth then\n            local north = s.fNorth\n            local dir = s.spin\n            -- Signs get cleared as the jumps resolve, so keep the last one seen.\n            if (me.marker or 0) ~= 0 then s.sign = me.marker end\n            local marker = s.sign or 0\n            local near = TensorCore.hasBuff(me.id, 3442)\n            local far = TensorCore.hasBuff(me.id, 3443)\n            local isBind = marker >= 6 and marker <= 8\n            -- Whichever of Attack 1/4 takes the north spot goes with the north group; Attack 2/3 are both south.\n            local slot\n            local elemental = values.elemental\n            if elemental then\n                -- Elemental automarkers (image sigma_am): Attack 1/2 bait the arms (1 follows the laser), Bind 1/2 are the\n                -- Near baits (1 at the mark, 2 four notches behind), Ignore 1/2 the Distant baits north/south.\n                isBind = marker == 1 or marker == 2\n                slot = (marker == 9 and 1) or (marker == 10 and 4) or (marker == 6 and 2) or (marker == 7 and 3) or nil\n            elseif marker == 1 or marker == 4 then\n                slot = s.pickSlot(me, marker, s.polar(north, 0, 19), s.polar(north, 180, 19))\n            end\n            local isNorth = isBind or slot == 1\n            local isSouth = slot == 4 or (not elemental and (marker == 2 or marker == 3)) or slot == 2 or slot == 3 or near or far\n            if not isNorth and not isSouth then\n                s.warnOnce(\"sign\", \"no sign or Hello World debuff for Part 2: \" .. tostring(marker))\n            end\n            if dir == nil then\n                if t >= 861.5 then s.warnOnce(\"spin\", \"spinner direction not seen\") end\n                addPolar(north, \"North group\", 0, 17, isNorth)\n                addPolar(north, \"South group\", 180, 17, isSouth)\n            elseif t < 873.75 then\n                -- Stage 6: behind the spinner's first shot. Blade feet leave the lane in line with her; staff waits at the wall.\n                if t >= 872 and s.isBlades() then\n                    addRel(north, \"North lane\", 0, -17, isNorth)\n                    addRel(north, \"South lane\", 0, 17, isSouth)\n                else\n                    addPolar(north, \"North group\", 22.5 * dir, 19, isNorth)\n                    addPolar(north, \"South group\", 180 + 22.5 * dir, 19, isSouth)\n                end\n            else\n                local done = t >= 878.25\n                local turned = math.min(s.SHOT_MAX, (t - s.SHOT_AT) * s.SHOT_RATE)\n                local tail = 180 - turned\n                local follows = isBind and (elemental and marker == 1 or (not elemental and s.bindFollows(me, dir)))\n                local bearing2, bearing3 = (done and 90 or tail + 25) * dir, (done and 112 or tail + 47) * dir\n                if not elemental and (marker == 2 or marker == 3) then\n                    slot = s.pickSlot(me, marker, s.polar(north, bearing2, 19), s.polar(north, bearing3, 19))\n                end\n                addPolar(north, \"Attack 1/4: Distant bait\", 0, 19, slot == 1)\n                addPolar(north, \"Attack 1/4: Distant bait\", 180, 19, slot == 4)\n                addPolar(north, \"Distant World\", 180, 9.5, far)\n                addPolar(north, \"Arm bait (follows)\", -45 * dir, 19, isBind and follows)\n                addPolar(north, done and \"Arm bait\" or \"Arm bait (wait)\", (done and 45 or 30) * dir, 19, isBind and not follows)\n                addPolar(north, \"Attack 2/3: Near bait\", bearing2, 19, slot == 2)\n                addPolar(north, \"Attack 2/3: Near bait\", bearing3, 19, slot == 3)\n                addPolar(north, \"Near World\", (done and 90 or tail + 42) * dir, 10, near)\n            end\n        end\n        s.spots = spots\n        s.mySpot = nil\n        for _, spot in ipairs(spots) do\n            if spot.mine then s.mySpot = spot end\n        end\n        local kind = s.mySpot and s.mySpot.label\n        if kind ~= s.lastKind then\n            s.lastKind = kind\n            if s.mySpot then\n                s.log(string.format(\"%.1f %s (%.1f,%.1f)\", t, kind, s.mySpot.x, s.mySpot.z))\n            end\n        end\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil then\n    self.used = true\n    return\nend\nlocal clock = Now()\nif s.nextPass == nil or clock >= s.nextPass then\n    s.nextPass = clock + 100\n    s.update(me, t)\nend\n\nlocal y = me.pos.y\nif values.sigSpots then\n    for _, spot in ipairs(s.spots or {}) do\n        if spot.mine then\n            s.drawMine:addCircle(spot.x, y, spot.z, 0.8)\n        else\n            s.drawRing:addCircle(spot.x, y, spot.z, 0.6)\n        end\n    end\nend\nlocal spot = s.mySpot\nif spot and values.sigArrow and me.hp.current > 0 then\n    local dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\n    local dist = math.sqrt(dx * dx + dz * dz)\n    if dist > 0.5 then\n        -- Sized like [Lj Draw] Arrow to Black Hole, except it keeps pointing up close.\n        local scale = math.min(1, dist / 15)\n        local near = math.min(1, dist / 3)\n        local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n        s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n            dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n            false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    end\nend\nself.used = true\n",
