							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P5 Run: Dynamis Omega, from the \"P5 - Omega... in greater detail\" guide: the two clone dodges, then Part 1 (true north,\n-- Final Omega's Monitor) and Part 2 (Beetle as north). Draws every spot for the step and marks mine.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topOmega\nif s == nil or (s.lastTime and (t < s.lastTime - 5 or Now() - (s.lastClock or Now()) > 5000)) then\n    s = {}\n    data.topOmega = s\nend\ns.lastTime = t\ns.lastClock = Now()\nif not values.omeSpots and not values.omeArrow then\n    s.spots = nil\n    self.used = true\n    return\nend\n\nif not s.initialized then\n    s.initialized = true\n    s.warned = {}\n    s.spots = {}\n    s.males, s.females, s.seen = {}, {}, {}\n    s.WAYMARK = { [0] = \"A\", [90] = \"B\", [180] = \"C\", [270] = \"D\" }\n    -- Only Attack 2/3 are interchangeable: the user removed the 1/4 flex (2026-11-08), so 1 and 4 keep their own spots.\n    s.PAIR = { [2] = 3, [3] = 2 }\n    -- Hold each dodge until the clones have hit, at 928.8 and 932.8.\n    s.DODGE_ENDS = { 929.0, 933.0 }\n    s.PART1_FROM, s.PART2_FROM, s.END = 936.1, 947.5, 965.5\n    -- Offsets are x east, z south with north up. Part 1 x is flipped so positive is the Monitor's safe side.\n    s.PART1 = {\n        { \"Attack 1/4\", 2, -19, 1 }, { \"Attack 1/4\", 2, 18.5, 4 }, { \"Attack 2/3\", 18.18, -3.68, 2 }, { \"Attack 2/3\", 18, 2.56, 3 },\n        { \"Near World\", 10.96, 0, \"near\" }, { \"Distant World\", 2, 11, \"far\" }, { \"Bind 1\", -9, -9, 6 }, { \"Bind 2\", -9, 9, 7 },\n    }\n    s.PART2 = {\n        { \"Attack 1/4\", -19, 0, 1 }, { \"Attack 1/4\", 19, 0, 4 }, { \"Attack 2/3\", -3, 18.5, 2 }, { \"Attack 2/3\", 3, 18.5, 3 },\n        { \"Near World\", 0, 10, \"near\" }, { \"Distant World\", -9.5, 0, \"far\" }, { \"Bind 1\", -11, -14.75, 6 }, { \"Bind 2\", 11, -14.75, 7 },\n    }\n    s.drawArrow = cfg.styledArrow(\"stOme\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawRing = TensorCore.getCachedDrawer(nil, nil, 0x44FFFFFF, 0xFFFFFFFF, 2)\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n\n    function s.log(text)\n        d(\"[Omega] \" .. text)\n        TensorCore.timelineLogToFile(\"[Omega] \" .. text .. \"\\n\")\n    end\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            s.log(text)\n        end\n    end\n\n    function s.bearingOf(x, z)\n        return math.deg(math.atan2(x - 100, 100 - z)) % 360\n    end\n\n    function s.gap(a, b)\n        return math.abs((a - b + 180) % 360 - 180)\n    end\n\n    function s.toWorld(north, x, z)\n        local a = math.rad(north)\n        local c, n = math.cos(a), math.sin(a)\n        return 100 + x * c - z * n, 100 + z * c + x * n\n    end\n\n    function s.find(content, model)\n        for id, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n            if Argus.getEntityModel(e) == model then return id, e end\n        end\n    end\n\n    -- Clones come in M/F pairs, a few seconds apart, on opposite intercards. Order of arrival is the order of the dodges.\n    function s.findClones()\n        local function scan(content, model, into)\n            for id, e in pairs(TensorCore.entityList(\"contentid=\" .. content)) do\n                if Argus.getEntityModel(e) == model and Argus.isEntityVisible(e) and not s.seen[id] then\n                    s.seen[id] = true\n                    into[#into + 1] = id\n                end\n            end\n        end\n        scan(12257, 15721, s.males)\n        scan(12258, 15722, s.females)\n    end\n\n    -- The F opposite this M is its pair.\n    function s.pairOf(male)\n        for _, id in ipairs(s.females) do\n            local f = TensorCore.mGetEntity(id)\n            if f and f.pos and s.gap(s.bearingOf(f.pos.x, f.pos.z), s.bearingOf(male.pos.x, male.pos.z)) > 150 then\n                return f\n            end\n        end\n    end\n\n    -- Flags 49 mean shield on M and blade feet on F. The casts settle it once they start.\n    function s.weapons(m, f)\n        local _, mFlags = Argus.getEntityTransforms(m)\n        local _, fFlags = Argus.getEntityTransforms(f)\n        local shield, blades = mFlags == 49, fFlags == 49\n        local mCast = m.castinginfo and m.castinginfo.channelingid\n        local fCast = f.castinginfo and f.castinginfo.channelingid\n        if mCast == 31525 then shield = true elseif mCast == 31526 then shield = false end\n        if fCast == 31533 then blades = false elseif fCast == 31530 or fCast == 31531 or fCast == 31532 then blades = true end\n        return shield, blades\n    end\n\n    -- Sword + feet goes toward F; everything else toward M. Radius by the guide's Close / Mid / Far.\n    function s.dodgeSpot(index)\n        local id = s.males[index]\n        local m = id and TensorCore.mGetEntity(id)\n        if m == nil or m.pos == nil or s.safeAxis == nil then return nil end\n        local f = s.pairOf(m)\n        if f == nil then return nil end\n        local shield, blades = s.weapons(m, f)\n        local target = (blades and not shield) and f or m\n        local name, radius = \"Far\", 17\n        if blades then\n            name, radius = \"Close\", 3\n        elseif shield then\n            name, radius = \"Mid\", 9.5\n        end\n        local want = s.bearingOf(target.pos.x, target.pos.z)\n        local axis = (s.safeAxis + (index == 1 and 0 or 90)) % 180\n        local card = axis\n        if s.gap(axis + 180, want) < s.gap(axis, want) then card = (axis + 180) % 360 end\n        card = (math.floor(card / 90 + 0.5) * 90) % 360\n        local a = math.rad(card)\n        return { x = 100 + radius * math.sin(a), z = 100 - radius * math.cos(a), label = name .. \" \" .. s.WAYMARK[card] }\n    end\n\n    function s.roleOf(me, inLine)\n        local near, far = TensorCore.hasBuff(me.id, 3442), TensorCore.hasBuff(me.id, 3443)\n        if (near or far) and TensorCore.hasBuff(me.id, inLine) then\n            return near and \"near\" or \"far\"\n        end\n        if (me.marker or 0) ~= 0 then s.sign = me.marker end\n        if values.mana and not values.elemental then\n            -- Mana (lodestone blog cheat sheet): Attack 1/2 take the monitors (Part 1) or the Beetle tethers (Part 2), Attack 3/4\n            -- the Distant baits, and the two players with nothing the Near soaks (the Attack 2/3 spots).\n            if s.sign == nil then return 2 end\n            local map = inLine == 3004 and s.MANA_SIGN1 or s.MANA_SIGN2\n            return map[s.sign]\n        end\n        if values.elemental and s.sign then\n            -- Elemental automarkers (images am1/am3) use the same spots with other signs: their Attack 1/2 take the Binds'\n            -- spots, their Bind 1/2 the Attack 2/3 spots, and Ignore 1/2 the Attack 1/4 spots.\n            return s.ELEMENTAL_SIGN[s.sign]\n        end\n        return s.sign\n    end\n    s.ELEMENTAL_SIGN = { [1] = 6, [2] = 7, [6] = 2, [7] = 3, [9] = 1, [10] = 4 }\n    -- Mana Part 1 (monitor side unsafe, as NA's frame): 1 the south monitor, 2 the north one, 3 south wall, 4 north wall.\n    -- Part 2 (Beetle north): 1 the west tether, 2 the east tether, 3 the west wall, 4 the east wall.\n    s.MANA_SIGN1 = { [1] = 7, [2] = 6, [3] = 4, [4] = 1 }\n    s.MANA_SIGN2 = { [1] = 6, [2] = 7, [3] = 1, [4] = 4 }\n    -- Mana moves Distant World: north of the middle in Part 1, east of it in Part 2.\n    s.PART1_MANA = {\n        { \"Attack 4 (north)\", 2, -19, 1 }, { \"Attack 3 (south)\", 2, 18.5, 4 }, { \"Near soak\", 18.18, -3.68, 2 }, { \"Near soak\", 18, 2.56, 3 },\n        { \"Near World\", 10.96, 0, \"near\" }, { \"Distant World\", 2, -10, \"far\" }, { \"Attack 2 (monitor)\", -9, -9, 6 }, { \"Attack 1 (monitor)\", -9, 9, 7 },\n    }\n    s.PART2_MANA = {\n        { \"Attack 3 (west)\", -19, 0, 1 }, { \"Attack 4 (east)\", 19, 0, 4 }, { \"Near soak\", -3, 18.5, 2 }, { \"Near soak\", 3, 18.5, 3 },\n        { \"Near World\", 0, 10, \"near\" }, { \"Distant World\", 6.5, 1, \"far\" }, { \"Attack 1 (tether)\", -11, -14.75, 6 }, { \"Attack 2 (tether)\", 11, -14.75, 7 },\n    }\n\n    -- Attack 2/3 are interchangeable: the pair takes whichever split means less total walking, then I keep my choice.\n    function s.pickSlot(me, mark, rows, place)\n        if s.slot then return s.slot end\n        local pair = s.PAIR[mark]\n        local low, high = math.min(mark, pair), math.max(mark, pair)\n        local spotLow, spotHigh\n        for _, row in ipairs(rows) do\n            if row[4] == low then\n                spotLow = { place(row) }\n            elseif row[4] == high then\n                spotHigh = { place(row) }\n            end\n        end\n        local function dist(e, spot)\n            return math.sqrt((e.pos.x - spot[1]) ^ 2 + (e.pos.z - spot[2]) ^ 2)\n        end\n        local other\n        for id in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            local e = TensorCore.mGetEntity(id)\n            -- Mana: the other Near soaker is the other player with no sign and no World debuff.\n            local manaPartner = values.mana and (e and (e.marker or 0) == 0) and not TensorCore.hasBuff(id, 3442) and not TensorCore.hasBuff(id, 3443)\n            if e and e.id ~= me.id and e.pos and (e.marker == pair or manaPartner) then other = e end\n        end\n        local lowCost, highCost = dist(me, spotLow), dist(me, spotHigh)\n        if other then\n            lowCost, highCost = lowCost + dist(other, spotHigh), highCost + dist(other, spotLow)\n        end\n        if math.abs(lowCost - highCost) < 0.01 then\n            s.slot = mark\n        else\n            s.slot = lowCost < highCost and low or high\n        end\n        s.log(string.format(\"sign %d takes the Attack %d spot, partner %s\", mark, s.slot, other and \"seen\" or \"not seen\"))\n        return s.slot\n    end\n\n    -- Part 2 with no sign marker, from the guide's AMless slide: the two players with 3 Quickening Dynamis (3444) take the Binds'\n    -- tethers, and the four with no World debuff and fewer stacks are the baits (1/4 east and west, 2/3 south). Who takes which spot\n    -- in each group is the split with the least total walking. It keeps its pick unless another is 2y better, and locks at 952.\n    s.DYNAMIS, s.STACK_LOCK = 3444, 952\n    function s.stackRole(me, t, rows, place)\n        if s.stackSlot and t >= s.STACK_LOCK then return s.stackSlot end\n        local function stacks(id)\n            local buff = TensorCore.getBuff(id, s.DYNAMIS)\n            return buff and (buff.stacks or 1) or 0\n        end\n        local function hello(id)\n            return TensorCore.hasBuff(id, 3442) or TensorCore.hasBuff(id, 3443)\n        end\n        local bind = stacks(me.id) >= 3\n        local slots = bind and { 6, 7 } or { 1, 2, 3, 4 }\n        local players = { me }\n        for id in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            local e = TensorCore.mGetEntity(id)\n            if e and e.id ~= me.id and e.pos and not hello(id) and (stacks(id) >= 3) == bind then players[#players + 1] = e end\n        end\n        if #players ~= #slots then\n            s.warnOnce(\"stacks\" .. tostring(bind), string.format(\"Part 2, no sign: %d players share my %s, want %d\", #players,\n                bind and \"3 Dynamis stacks\" or \"bait role\", #slots))\n            return nil\n        end\n        local spotOf = {}\n        for _, row in ipairs(rows) do\n            for _, slot in ipairs(slots) do\n                if row[4] == slot then spotOf[slot] = { place(row) } end\n            end\n        end\n        local function cost(order)\n            local total = 0\n            for i, e in ipairs(players) do\n                local spot = spotOf[order[i]]\n                total = total + math.sqrt((e.pos.x - spot[1]) ^ 2 + (e.pos.z - spot[2]) ^ 2)\n            end\n            return total\n        end\n        local best, bestCost\n        local function permute(list, used, depth)\n            if depth > #slots then\n                local c = cost(list)\n                if bestCost == nil or c < bestCost then\n                    best, bestCost = {}, c\n                    for i = 1, #list do best[i] = list[i] end\n                end\n                return\n            end\n            for _, slot in ipairs(slots) do\n                if not used[slot] then\n                    used[slot] = true\n                    list[depth] = slot\n                    permute(list, used, depth + 1)\n                    used[slot] = nil\n                end\n            end\n        end\n        permute({}, {}, 1)\n        -- Me first in the list, so my slot is the first in the order. Keep the old pick unless the new one is 2y better.\n        if s.stackOrder and #s.stackOrder == #slots and bestCost + 2 >= cost(s.stackOrder) then\n            best = s.stackOrder\n        end\n        if s.stackSlot ~= best[1] then\n            s.log(string.format(\"%.1f Part 2, no sign: %d Dynamis stacks, I take %s\", t, stacks(me.id), s.NAMES[best[1]]))\n        end\n        s.stackOrder, s.stackSlot = best, best[1]\n        return s.stackSlot\n    end\n    s.NAMES = { \"Attack 1\", \"Attack 2\", \"Attack 3\", \"Attack 4\", nil, \"Bind 1\", \"Bind 2\" }\n\n    function s.addPart(me, rows, role, place, add, exact)\n        local mine = role\n        if s.PAIR[role] and not exact then mine = s.pickSlot(me, role, rows, place) end\n        for _, row in ipairs(rows) do\n            local x, z = place(row)\n            add(row[1], x, z, row[4] == mine)\n        end\n    end\n\n    function s.update(me, t)\n        local spots = {}\n        local function add(label, x, z, mine)\n            spots[#spots + 1] = { label = label, x = x, z = z, mine = mine and true or false }\n        end\n        local omegaID, omega = s.find(7636, 14669)\n        local channel = omega and omega.castinginfo and omega.castinginfo.channelingid\n        if s.safeAxis == nil and omega and (channel == 31644 or channel == 31643) then\n            -- 31644 cleaves Omega's sides first, 31643 her front and back first.\n            local facing = (180 - math.deg(omega.pos.h)) % 180\n            s.safeAxis = channel == 31644 and facing or (facing + 90) % 180\n            s.log(string.format(\"%.1f first safe axis %.0f\", t, s.safeAxis))\n        end\n        if s.safeSide == nil and (channel == 31638 or channel == 31639) then\n            s.safeSide = channel == 31638 and -1 or 1\n            s.log(string.format(\"%.1f Monitor cast %d\", t, channel))\n        end\n        if t < s.DODGE_ENDS[2] + 0.5 then\n            s.findClones()\n        end\n\n        if t < s.DODGE_ENDS[2] then\n            local now = t < s.DODGE_ENDS[1] and 1 or 2\n            local spot = s.dodgeSpot(now)\n            if spot then add(\"Dodge \" .. now .. \": \" .. spot.label, spot.x, spot.z, true) end\n            if now == 1 then\n                local nextSpot = s.dodgeSpot(2)\n                if nextSpot then add(\"Next: \" .. nextSpot.label, nextSpot.x, nextSpot.z, false) end\n            end\n        elseif t >= s.PART1_FROM and t < s.PART2_FROM then\n            local role = s.roleOf(me, 3004)\n            if s.safeSide then\n                local mana = values.mana and not values.elemental\n                s.addPart(me, mana and s.PART1_MANA or s.PART1, role, function(row) return 100 + row[2] * s.safeSide, 100 + row[3] end, add,\n                    values.elemental or (mana and role ~= 2))\n                if role == nil then s.warnOnce(\"role1\", \"Part 1: no sign or first-in-line debuff\") end\n            end\n        elseif t >= s.PART2_FROM and t < s.END then\n            if not s.part2 then\n                s.part2, s.sign, s.slot = true, nil, nil\n            end\n            local _, beetle = s.find(7695, 15724)\n            if beetle and s.north == nil then\n                s.north = math.floor(s.bearingOf(beetle.pos.x, beetle.pos.z) / 90 + 0.5) * 90 % 360\n                s.log(string.format(\"%.1f Beetle north %.0f\", t, s.north))\n            end\n            local role = s.roleOf(me, 3005)\n            if s.north then\n                local place = function(row) return s.toWorld(s.north, row[2], row[3]) end\n                local exact = false\n                if role == nil then\n                    role = s.stackRole(me, t, s.PART2, place)\n                    exact = role ~= nil\n                end\n                local mana = values.mana and not values.elemental\n                s.addPart(me, mana and s.PART2_MANA or s.PART2, role, place, add, exact or values.elemental or (mana and role ~= 2))\n                if role == nil then s.warnOnce(\"role2\", \"Part 2: no sign, second-in-line debuff or Dynamis stack role\") end\n            elseif t >= 949 then\n                s.warnOnce(\"beetle\", \"Beetle not found\")\n            end\n        end\n        s.spots = spots\n        s.mySpot = nil\n        for _, spot in ipairs(spots) do\n            if spot.mine then s.mySpot = spot end\n        end\n        local kind = s.mySpot and s.mySpot.label\n        if kind ~= s.lastKind then\n            s.lastKind = kind\n            if s.mySpot then s.log(string.format(\"%.1f %s (%.1f,%.1f)\", t, kind, s.mySpot.x, s.mySpot.z)) end\n        end\n    end\nend\n\nlocal me = TensorCore.mGetPlayer()\nif me == nil or me.pos == nil then\n    self.used = true\n    return\nend\nlocal clock = Now()\nif s.nextPass == nil or clock >= s.nextPass then\n    s.nextPass = clock + 100\n    s.update(me, t)\nend\n\nlocal y = me.pos.y\nif values.omeSpots then\n    for _, spot in ipairs(s.spots or {}) do\n        if spot.mine then\n            s.drawMine:addCircle(spot.x, y, spot.z, 0.8)\n        else\n            s.drawRing:addCircle(spot.x, y, spot.z, 0.6)\n        end\n    end\nend\nlocal spot = s.mySpot\nif spot and values.omeArrow and me.hp.current > 0 then\n    local dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\n    local dist = math.sqrt(dx * dx + dz * dz)\n    if dist > 0.5 then\n        -- Sized like [Lj Draw] Arrow to Black Hole, except it keeps pointing up close.\n        local scale = math.min(1, dist / 15)\n        local near = math.min(1, dist / 3)\n        local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n        s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n            dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n            false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\n    end\nend\nself.used = true\n",
