						{
							aType = "ACR",
							conditions = 
							{
								
								{
									"d70e92f4-0bc4-56a1-b54f-bc736f19dd1b",
									true,
								},
								
								{
									"c19439f7-90bc-2dce-86dd-f6d461d43079",
