					{
						data = 
						{
							aType = "Lua",
							actionLua = "-- [Looper] Options settings, saved to LuaMods\\TensorReactions\\TopLooperSettings.lua.\nlocal cfg = data.topLooperSettings\nif cfg == nil or cfg.version ~= 40 then\n    cfg = {\n        version = 40,\n        path = GetLuaModsPath() .. [[TensorReactions\\TopLooperSettings.lua]],\n        -- Distances and the angle are measured from the guide's slides.\n        defaults = {\n            -- All mechanics\n            rosterOpen = true, labelSize = 2, tts = true, calloutOn = true, mitOn = true, elemental = false, oce = false, ldpu = false, mana = false,\n            -- P1\n            arrow = true, nextRing = true, callouts = true, topUp = true,\n            tetherRadius = 16, tetherAngle = 7, grabDistance = 5, towerOffset = 1.5,\n            panCallouts = true,\n            -- P2\n            synArrow = true, synSpots = true, synLabels = true, synOthers = false, synFlex = true, synKnock = true, limTank = true,\n            -- Which Party Synergy stack flexes: the strat's rule, or always the one closest to / furthest from the eye.\n            synFlexRule = \"Strat default\",\n            -- P3\n            intArrow = true, intSpots = true, intLabels = true,\n            helArrow = true, helSpots = true, helLabels = true, helConga = true,\n            monArrow = true, monRing = true, monFace = true, monFacing = false, monSouth = 0,\n            -- P5\n            delArrow = true, delSpots = true, delLabels = true, delOthers = false, delBreak = true, delSwap = true,\n            delMonitor = true, delFace = true, delOtherBeams = false, delBossHalf = false,\n            sigArrow = true, sigSpots = true, sigLabels = true, sigOthers = false,\n            omeArrow = true, omeSpots = true, omeLabels = true, omeClones = false, omeSafe = true, omePreview = false,\n            worldDraw = true,\n            -- P6\n            exaArrow = true, exaZone = false, exaSafe = true, exaDpsSupport = false,\n            uwcArrow = true,\n            clkWave = true, clkMeteor = true, clkFlare = true,\n            -- Boss attack draws, from the game's own AOE data\n            synAoe = true, limAoe = true, wcAoe = true, delAoe = true, sigAoe = true,\n            -- Guide style per mechanic, like Frog Draws: \"Arrow\" or \"Tether\" (a line from me to the spot).\n            stLoop = \"Arrow\", stSyn = \"Arrow\", stLim = \"Arrow\", stInt = \"Arrow\", stHel = \"Arrow\", stMon = \"Arrow\",\n            stDel = \"Arrow\", stSig = \"Arrow\", stOme = \"Arrow\", stExa = \"Arrow\", stUwc = \"Arrow\", stClk = \"Arrow\",\n        },\n        values = {},\n    }\n    cfg.STYLE_KEYS = { \"stLoop\", \"stSyn\", \"stLim\", \"stInt\", \"stHel\", \"stMon\", \"stDel\", \"stSig\", \"stOme\", \"stExa\", \"stUwc\", \"stClk\" }\n    -- Stands in for a script's arrow drawer: the usual arrow, or with that mechanic set to \"Tether\", a red line from me to the\n    -- spot. The arrow's start, heading and length give the spot (game heading: 0 south, pi/2 east). Reads the live setting.\n    function cfg.styledArrow(key, real)\n        local proxy = {}\n        function proxy.addArrow(_, x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            local live = data.topLooperSettings\n            if live and live.values[key] == \"Tether\" then\n                local reach = length + tipLength\n                if live.tetherDrawer == nil then\n                    local overlay = Argus2 and Argus2.RenderFlags and Argus2.RenderFlags.FLAG_RENDER_OVERLAY or 0\n                    live.tetherDrawer = TensorCore.getCachedDrawer(nil, nil, 0xFF0000FF, 0xFFFFFFFF, 2, 0, overlay)\n                end\n                live.tetherDrawer:addLine(x, y, z, x + math.sin(heading) * reach, y, z + math.cos(heading) * reach, 8, 3)\n            else\n                real:addArrow(x, y, z, heading, length, width, tipLength, tipWidth, ...)\n            end\n        end\n        return proxy\n    end\n    local loaded = FileExists(cfg.path) and FileLoad(cfg.path)\n    if type(loaded) ~= \"table\" then loaded = {} end\n    for key, default in pairs(cfg.defaults) do\n        if type(loaded[key]) == type(default) then\n            cfg.values[key] = loaded[key]\n        else\n            cfg.values[key] = default\n        end\n    end\n    data.topLooperSettings = cfg\n    -- Who's who for the flex. Sometimes a pull starts with only me in the party list, so the Roster never gets ready:\n    -- then match its saved jobs to the players around me and do the same flex here.\n    cfg.rosterView = function(Roster, me)\n        if Roster.isReady() then\n            return { ready = true, groups = Roster.groups, idOf = Roster.idOf, slotOf = Roster.slotOf,\n                     resolveFlex = Roster.resolveFlex, mySlot = Roster.mySlot,\n                     publish = function(key, byId)\n                         Roster.pull.set(key, byId)\n                         return Roster.my(key)\n                     end }\n        end\n        local saved = Roster.current()\n        if saved == nil or saved.members == nil or saved.jobs == nil then return nil end\n        local slotOfJob = {}\n        for guid, slot in pairs(saved.members) do\n            if saved.jobs[guid] == nil then return nil end\n            slotOfJob[saved.jobs[guid]] = slot\n        end\n        local ids, slots, count = {}, {}, 0\n        local function add(id, job)\n            local slot = slotOfJob[job]\n            if slot and ids[slot] == nil then\n                ids[slot], slots[id] = id, slot\n                count = count + 1\n            end\n        end\n        add(me.id, me.job)\n        for id, e in pairs(TensorCore.entityList(\"type=1,chartype=4\")) do\n            add(id, e.job)\n        end\n        if count ~= 8 then return nil end\n        local view = { ready = false }\n        function view.idOf(slot) return ids[slot] end\n        function view.slotOf(id) return slots[id] end\n        function view.mySlot() return slots[me.id] end\n        function view.publish(_, byId) return byId[me.id] end\n        function view.groups(name)\n            if name == \"g1\" then return { ids.T1, ids.M1, ids.R1, ids.H1 } end\n            return { ids.T2, ids.M2, ids.R2, ids.H2 }\n        end\n        -- In a group holding the same line twice, the higher priority player swaps across.\n        function view.resolveFlex(args)\n            local rank, i = {}, 0\n            for slot in args.prio:gmatch(\"%S+\") do\n                i = i + 1\n                rank[ids[slot]] = i\n            end\n            local function movers(list)\n                local seen, moved = {}, {}\n                for _, id in ipairs(list) do\n                    local line = args.attrOf[id]\n                    if seen[line] then\n                        moved[#moved + 1] = rank[id] < rank[seen[line]] and id or seen[line]\n                    else\n                        seen[line] = id\n                    end\n                end\n                return moved\n            end\n            local one, two = movers(args.groups.g1), movers(args.groups.g2)\n            local function after(list, leave, join)\n                local result = {}\n                for _, id in ipairs(list) do\n                    local gone = false\n                    for _, other in ipairs(leave) do\n                        if other == id then gone = true end\n                    end\n                    if not gone then result[#result + 1] = id end\n                end\n                for _, id in ipairs(join) do result[#result + 1] = id end\n                return result\n            end\n            local swaps = {}\n            for n = 1, #one do swaps[n] = { a = one[n], b = two[n] } end\n            return { g1 = after(args.groups.g1, one, two), g2 = after(args.groups.g2, two, one) }, swaps\n        end\n        return view\n    end\nend\n\n-- TOP P6: an arrow to my own spot, from the 5th puddle of the first Unlimited Wave Cannon, then at Cosmo Meteor after the bait and for\n-- its Flare markers. The spots are the user's: at Cosmo Meteor T1 trades with the LB3 player, the physical ranged, who takes N.\nlocal values = cfg.values\nlocal t = TensorReactions_CurrentTimer\nlocal s = data.topClock\n-- data outlives a redeploy, so a new revision rebuilds the tables below instead of keeping an older copy's.\nlocal REV = \"2026-11-08-style\"\nif s == nil or s.rev ~= REV then\n    s = { warned = {}, rev = REV }\n    data.topClock = s\n    s.SPOTS = {\n        -- NA strat (the user, 2026-11-08): R2 NE and R1 NW, as in P3.\n        wave = { T1 = 0, R2 = 45, H2 = 90, M2 = 135, T2 = 180, M1 = 225, H1 = 270, R1 = 315 },\n        -- Elemental (06_alpha_omega, images 2_4 and 5_2): MT NW, D3 N, D4 NE, H2 E, D2 SE, ST S, D1 SW, H1 W, for the Wave Cannon\n        -- spread and the Cosmo Meteor spread alike (D3, the ranged LB3, is already north).\n        elemental = { T1 = 315, R1 = 0, R2 = 45, H2 = 90, M2 = 135, T2 = 180, M1 = 225, H1 = 270 },\n        -- LDPU (raidplan mh3bX4KJ9d8rT9nk): ranged by job, P = the physical ranged, C = the caster. Wave Cannon 1: MT N, Caster\n        -- NE, OT E, M2 SE, H2 S, M1 SW, H1 W, Phys NW. Cosmo Meteor: Phys N, MT NW, Caster NE, H2 E, M2 SE, OT S, M1 SW, H1 W.\n        ldpuWave = { T1 = 0, C = 45, T2 = 90, M2 = 135, H2 = 180, M1 = 225, H1 = 270, P = 315 },\n        ldpuMeteor = { P = 0, C = 45, H2 = 90, M2 = 135, T2 = 180, M1 = 225, H1 = 270, T1 = 315 },\n    }\n    s.WINDOWS = {\n        { 1228.42, 1236.7, \"wave\", \"clkWave\" },\n        -- From just after the baits are placed (1331.6), so I leave the middle puddle before it lands (the user, 2026-11-08).\n        { 1331.7, 1343.85, \"meteor\", \"clkMeteor\" },\n        { 1346.71, 1354.86, \"flare\", \"clkFlare\" },\n    }\n    s.RADIUS, s.WALL = 12, 19\n    -- Elemental Flares (images 5_8a/5_8b): the stack and D3's north spot at about 12.8, the other Flares at about 14.2.\n    function s.stackR() return values.elemental and 12.8 or s.RADIUS end\n    function s.flareR() return values.elemental and 14.2 or s.WALL end\n    s.FLARE_LOCK = 1351.7\n    -- The 6th puddle's bait in the logged pulls.\n    s.SIXTH = 1230.45\n    s.drawArrow = cfg.styledArrow(\"stClk\", TensorCore.getCachedDrawer(0xFF00FFFF, 0xFF0088FF, 0xFF0000FF, 0xFFFFFFFF, 2))\n    s.drawMine = TensorCore.getCachedDrawer(nil, nil, 0x6600FF00, 0xFF00FF00, 2)\n\n    -- BRD, MCH or DNC. The user's party has theirs at R2, others at R1. With both or neither, R2 does it.\n    -- My own entity isn't always in the entity list, so I read my job from me: the 09:14 pull's Machinist got no north arrow.\n    function s.lbSlot(view, me)\n        -- Elemental and Mana (\"If D3 has a Flare, stack on C\"): D3 (R1) is always the ranged LB3.\n        if values.elemental or values.mana then return \"R1\" end\n        local PHYSICAL = { [23] = true, [31] = true, [38] = true }\n        local function physical(slot)\n            local id = view.idOf(slot)\n            if id == nil then return false end\n            if me and id == me.id then return PHYSICAL[me.job] == true end\n            local e = TensorCore.mGetEntity(id)\n            return e ~= nil and PHYSICAL[e.job] == true\n        end\n        if physical(\"R1\") and not physical(\"R2\") then return \"R1\" end\n        return \"R2\"\n    end\n\n    -- OCE (MUR cheatsheet \"Pure Healer Centre after AoE\"): the WHM or AST goes to the middle once the bait puddles land (31666,\n    -- 1331.6 + 3.7s in the logs). H1 when both or neither are.\n    s.PUDDLES_LAND = 1335.35\n    function s.pureSlot(view, me)\n        local PURE = { [24] = true, [33] = true }\n        local function pure(slot)\n            local id = view.idOf(slot)\n            if id == nil then return false end\n            if me and id == me.id then return PURE[me.job] == true end\n            local e = TensorCore.mGetEntity(id)\n            return e ~= nil and PURE[e.job] == true\n        end\n        if pure(\"H2\") and not pure(\"H1\") then return \"H2\" end\n        return \"H1\"\n    end\n\n    function s.warnOnce(key, text)\n        if not s.warned[key] then\n            s.warned[key] = true\n            d(\"[Clock Spot] \" .. text)\n            TensorCore.timelineLogToFile(\"[Clock Spot] \" .. text .. \"\\n\")\n        end\n    end\n\n    function s.at(bearing, radius)\n        local a = math.rad(bearing)\n        return { x = 100 + radius * math.sin(a), z = 100 - radius * math.cos(a) }\n    end\n\n    function s.walk(id, spot)\n        local e = TensorCore.mGetEntity(id)\n        if e == nil or e.pos == nil then return 0 end\n        return math.sqrt((e.pos.x - spot.x) ^ 2 + (e.pos.z - spot.z) ^ 2)\n    end\n\n    -- Every way to give these players these cardinals, walled at r=19: the shortest total walk. Keeps its pick unless another is 2y better.\n    function s.assign(ids, cardinals, t)\n        local best, bestCost\n        local current = 0\n        local function try(list, used, depth)\n            if depth > #ids then\n                local cost = 0\n                for i, id in ipairs(ids) do cost = cost + s.walk(id, s.at(list[i], s.flareR())) end\n                if bestCost == nil or cost < bestCost then\n                    best, bestCost = {}, cost\n                    for i, id in ipairs(ids) do best[id] = list[i] end\n                end\n                return\n            end\n            for _, bearing in ipairs(cardinals) do\n                if not used[bearing] then\n                    used[bearing] = true\n                    list[depth] = bearing\n                    try(list, used, depth + 1)\n                    used[bearing] = nil\n                end\n            end\n        end\n        try({}, {}, 1)\n        if s.picked ~= nil then\n            for _, id in ipairs(ids) do current = current + s.walk(id, s.at(s.picked[id], s.flareR())) end\n            if t >= s.FLARE_LOCK or bestCost + 2 >= current then return s.picked end\n        end\n        s.picked = best\n        return best\n    end\n\n    function s.flareSpot(me, view, t)\n        local flares = data.topClockFlares\n        local count, ids = 0, {}\n        local lb = view.idOf(s.lbSlot(view, me))\n        local lbFlare = false\n        for id in pairs(flares and flares.ids or {}) do\n            count = count + 1\n            if id == lb then lbFlare = true else ids[#ids + 1] = id end\n        end\n        if count ~= 3 then\n            s.warnOnce(\"flares\", string.format(\"%d of 3 Flare markers seen\", count))\n            return nil\n        end\n        table.sort(ids)\n        local stack = s.at(lbFlare and 180 or 0, s.stackR())\n        if me.id == lb and lbFlare then return s.at(0, s.stackR()) end\n        if not flares.ids[me.id] then return stack end\n        local picked = s.assign(ids, lbFlare and { 90, 270 } or { 90, 180, 270 }, t)\n        return s.at(picked[me.id], s.flareR())\n    end\nend\n\nlocal active\nfor _, row in ipairs(s.WINDOWS) do\n    if t >= row[1] and t < row[2] then active = row end\nend\n-- The guide goes to clock spots after the 6th puddle (the user, 2026-11-08): wait for it, or for its usual time if it wasn't seen.\nif active ~= nil and active[3] == \"wave\" then\n    local uwc = data.topUwc\n    local sixth = uwc ~= nil and Now() - uwc.at < 30000 and #uwc.baits >= 6\n    if not sixth and t < s.SIXTH then active = nil end\nend\nlocal me = TensorCore.mGetPlayer()\nif active ~= nil and not values[active[4]] then\n    s.warnOnce(\"off\" .. active[3], active[3] .. \": its option (\" .. active[4] .. \") is off\")\nend\nif active == nil or not values[active[4]] or me == nil or me.pos == nil then\n    self.used = true\n    return\nend\n-- Frames stop between windows and pulls, so each new stretch starts with a clean log and a fresh Flare split.\nif s.lastClock == nil or Now() - s.lastClock > 5000 then\n    s.warned, s.picked = {}, nil\nend\ns.lastClock = Now()\nlocal Roster = AnyoneCore and AnyoneCore.Roster\nlocal view = Roster and Roster.current() ~= nil and cfg.rosterView(Roster, me) or nil\nif view == nil then\n    s.warnOnce(\"roster\", \"no Party Roster: can't tell my spot\")\n    self.used = true\n    return\nend\nlocal spot\nif active[3] == \"flare\" then\n    spot = s.flareSpot(me, view, t)\nelse\n    local slot = view.mySlot()\n    local bearing = (values.elemental and s.SPOTS.elemental or s.SPOTS.wave)[slot]\n    if values.ldpu then\n        local key = slot\n        if slot == \"R1\" or slot == \"R2\" then\n            local ok, lb = pcall(s.lbSlot, view, me)\n            if not ok then lb = \"R2\" end\n            key = slot == lb and \"P\" or \"C\"\n        end\n        bearing = (active[3] == \"meteor\" and s.SPOTS.ldpuMeteor or s.SPOTS.ldpuWave)[key]\n    elseif active[3] == \"meteor\" and not values.elemental then\n        local ok, lb = pcall(s.lbSlot, view, me)\n        if not ok then\n            s.warnOnce(\"meteorErr\", \"Cosmo Meteor: LB3 player lookup failed: \" .. tostring(lb))\n            lb = \"R2\"\n        end\n        if slot == lb then\n            bearing = 0\n        elseif slot == \"T1\" then\n            bearing = s.SPOTS.wave[lb]\n        end\n    end\n    if bearing then spot = s.at(bearing, s.RADIUS) end\n    if active[3] == \"meteor\" and values.oce and t >= s.PUDDLES_LAND then\n        local ok, pure = pcall(s.pureSlot, view, me)\n        if ok and slot == pure then\n            spot, bearing = { x = 100, z = 100 }, \"middle\"\n        end\n    end\n    -- One line per window in the fight log, so a pull shows what this decided.\n    s.warnOnce(\"pick\" .. active[3], string.format(\"%s: my slot %s, bearing %s\", active[3], tostring(slot), tostring(bearing)))\nend\nif spot == nil then\n    self.used = true\n    return\nend\nlocal y = me.pos.y\ns.drawMine:addCircle(spot.x, y, spot.z, 0.8)\nlocal dx, dz = spot.x - me.pos.x, spot.z - me.pos.z\nlocal dist = math.sqrt(dx * dx + dz * dz)\nif dist > 0.5 and me.hp.current > 0 then\n    -- Sized like [Lj Draw] Arrow to Black Hole, except it keeps pointing up close.\n    local scale = math.min(1, dist / 15)\n    local near = math.min(1, dist / 3)\n    local tipLength = math.min(math.max(2, 3 * scale), dist * 2 / 3)\n    s.drawArrow:addArrow(me.pos.x, y, me.pos.z, TensorCore.getHeadingToTarget2(me.pos.x, y, me.pos.z, spot.x, y, spot.z),\n        dist - tipLength, math.max(0.5, scale) * near, tipLength, math.max(1.5, 3 * scale) * near,\n        false, Argus2.RenderFlags.FLAG_RENDER_OVERLAY)\nend\nself.used = true\n",
